(function(global){
'use strict';
const RA=global.RA=global.RA||{};
const D=(w,p)=>RA.D(w,p);
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:w==='toronto'?'City of Toronto: https://www.toronto.ca/wp-content/uploads/2023/07/9869-IG-TNO-Online-Compressed.pdf':w==='topi'?'Collins English Dictionary: https://www.collinsdictionary.com/dictionary/english/topi':'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('topcoat','Topcoat is a transparent compound of top and coat; it names an outer coat worn over other clothes and the last protective paint layer applied over a base coat.',[C('topcoat.s1','衣物','She threw on a warm topcoat before walking to the station in the snow.','她下雪天去车站前套上了一件暖和的大衣。','wear/put on a topcoat; a wool topcoat','名词，指穿在其他衣服外面的长外套，尤指保暖大衣。','the garment is an outer layer of clothing.','衣物'),C('topcoat.s2','涂层','Apply the topcoat only after the base coat has dried completely.','底漆完全干透后再涂面漆。','apply a topcoat; protective topcoat','名词，指涂在底漆上方的最后一层保护漆。','the layer goes on top of the base coat.','涂层')],M('She applied the topcoat first, then covered it with a base coat as the final protective layer.','She applied the base coat first and finished with the protective topcoat.','topcoat是涂在底漆上方的面漆，不是第一层底漆。','meaning'),[Q(1,'A winter topcoat is…','an outer garment worn over other clothes','a thin layer of paint','a fast-moving stream','Sense 1 is the clothing meaning.','meaning'),Q(2,'When should painters apply the topcoat?','After the base coat has dried','Before putting on the base coat','Instead of preparing the surface','Sense 2 is the final paint layer.','context'),Q(1,'Which phrase is natural?','put on a topcoat','put a topcoat on the wall as clothing','topcoat wear overly','Put on is a natural clothing collocation.','collocation'),Q(1,'Topcoat combines…','top and coat','top and soil','torque and coat','The compound describes a coat on top or a top paint layer.','word-formation')]);
P('topi','For the sun helmet, topi comes from Hindi/Urdu topi, “hat”; the African antelope name is a separate usage whose deeper origin is uncertain in the available source.',[C('topi.s1','帽子','He wore a light topi to protect his head from the midday sun.','他戴了一顶轻便遮阳帽，防护正午的阳光。','wear a topi; pith topi','名词，指在炎热地区佩戴的轻便遮阳头盔，也称pith helmet。','the headwear shades him from strong sunlight.','帽子'),C('topi.s2','羚羊','A topi grazed on the open plain while the rest of the herd watched.','一只羚羊在开阔平原上吃草，羊群中的其他成员在旁观察。','topi antelope; a herd of topi','名词，指一种有棱角长角的大型非洲羚羊。','the animal is grazing as part of a herd.','羚羊')],M('He wore a topi to keep his head warm in the Arctic winter, though the word names a light sun helmet.','He wore a topi to shade his head from the tropical sun.','topi的帽子义是遮阳帽，不是严寒保暖帽。','meaning'),[Q(1,'A topi used against noon sun is…','a light sun helmet','a species of seabird','a layer of paint','Sense 1 is the headwear meaning.','meaning'),Q(2,'The topi grazing on the plain is…','an African antelope','a person wearing a hat','a landform map','Sense 2 is the animal use.','context'),Q(1,'Which phrase is natural?','wear a topi in strong sun','wear a topi as a wool coat','topi the sun head','The example uses topi as headwear.','collocation'),Q(1,'The helmet sense of topi was borrowed from…','Hindi or Urdu for “hat”','Latin for a boundary','Greek for “fear”','The headwear name is from a South Asian word.','word-formation')]);
P('topic','Topic comes through Latin from Greek topikos, “of a place,” from topos, “place”; it now means the subject under discussion or one item in a study list.',[C('topic.s1','话题','The topic of the essay is how public parks improve city life.','这篇作文的话题是公共公园如何改善城市生活。','topic of discussion; change/raise a topic','名词，指谈话、课程或文章讨论的主题。','the essay focuses on one subject.','话题'),C('topic.s2','学习项目','The course guide lists each topic students must revise before the final exam.','课程指南列出学生期末考试前必须复习的每个学习项目。','cover/revise a topic; topic on the syllabus','名词，指课程或研究计划中的一个具体内容单元。','each item forms part of a syllabus.','学习项目')],M('The topic of the essay was parks, but every paragraph avoided parks and discussed astronomy instead.','The topic of the essay was parks, and each paragraph explained one way parks affect city life.','topic是文章实际讨论的主题；内容转为天文学便与所给主题不符。','meaning'),[Q(1,'The topic of an essay is…','the subject it discusses','a test of blood','the land at the end of a route','That is the writing sense.','meaning'),Q(2,'A topic on the course guide is…','one item students need to study','a final paint layer','a violent storm','Sense 2 is a study unit.','context'),Q(1,'Which phrase is natural?','raise a topic in class','raise a topic to classly','topic raise of in','Raise a topic means introduce it for discussion.','collocation'),Q(1,'Greek topos, behind topic, meant…','place','hat','twist','The original word referred to a place or subject area.','word-formation')]);
P('topical','Topical comes through Latin from Greek topikos, “of a place”; it first meant local or related to a subject and now often means current, while medicine uses it for something applied to the body’s surface.',[C('topical.s1','时事/主题','The editor chose a topical question about housing costs for this week’s debate.','编辑为本周辩论选了一个有关住房成本的时事话题。','topical issue/question; topical humour','形容词，指与当前受到关注的事件或话题有关的。','housing prices are a current public concern.','时事/主题'),C('topical.s2','外用','The doctor prescribed a topical cream that should be applied to the rash, not swallowed.','医生开了一种外用乳膏，应涂在皮疹上而不能吞服。','topical cream/ointment; topical treatment','形容词，医学上指涂在身体表面而非内服的。','the medicine is applied externally.','外用')],M('She swallowed the topical cream because topical means intended to be taken by mouth.','She applied the topical cream to the rash as directed.','医学中的topical指外用、涂于表面，不是口服。','meaning'),[Q(1,'A topical housing question concerns…','a current issue of public interest','a subject no one discusses','a land survey only','Sense 1 is the current-affairs use.','meaning'),Q(2,'A topical cream is…','applied to the outside of the body','swallowed as a drink','a helmet worn in the sun','Sense 2 is the medical use.','context'),Q(1,'Which phrase is natural?','a topical treatment for a rash','a topical treatment to swallow','topically cream treatment','Topical treatment is the standard medical collocation.','collocation'),Q(1,'Topical is historically related to Greek topos, meaning…','place','water','fear','The early adjective meant connected with a place or subject.','word-formation')]);
P('topographical','Topographical is formed from topography with -ical; it describes detailed representation or study of a region’s surface features, such as relief, rivers, and roads.',C('topographical.s1','地图','The topographical map marks contour lines, streams, and roads across the valley.','这张地形图标出了山谷中的等高线、溪流和道路。','topographical map/survey; topographical features','形容词，指与地表特征的详细测绘或描绘有关。','the map records the shapes and features of the land.','地图'),M('The topographical map omitted every hill, river, and road and showed only the weather forecast.','The topographical map recorded the hills, rivers, roads, and contour lines.','topographical map用于描绘地形，而不是只提供天气预报。','meaning'),[Q(1,'A topographical map typically shows…','land contours and surface features','the plot of a theatre play','the level of political support','That is the mapping sense.','meaning'),Q(1,'Which features are marked in the example?','Contour lines, streams, and roads','Only ticket prices','Only chemical toxins','The context names details of the valley’s surface.','context'),Q(1,'Which phrase is standard?','topographical survey','topography surveyingly','survey topographicalness','Topographical modifies survey as an adjective.','grammar'),Q(1,'Topographical is formed from…','topography plus -ical','topic plus -less','topsoil plus -ing','The suffix makes an adjective meaning related to topography.','word-formation')]);
P('topographically','Topographically is formed from topographical plus -ly; it means in terms of the arrangement and physical features of land.',C('topographically.s1','地形比较','The two valleys are topographically similar, although they lie on different continents.','这两座山谷的地形相似，尽管它们位于不同大陆。','topographically similar/different; compare topographically','副词，指从地形排列或地表特征来看。','the comparison is about their physical landforms.','地形比较'),M('The valleys are topographically similar because one is mountainous and the other is a flat plain.','The valleys are topographically different because one is mountainous and the other is flat.','一处山地和一处平原的地形不同，不能据此称为相似。','meaning'),[Q(1,'Topographically similar valleys share…','similar arrangements of landforms','the same political government','the same theatre building','The adverb limits similarity to physical terrain.','meaning'),Q(1,'What differs between the valleys?','Their continents','Their topography','The fact that either has landforms','The sentence says they share topography but lie on different continents.','context'),Q(1,'Which phrase is natural?','compare the valleys topographically','topographically compare of valleys','topographical similar in valleyly','Topographically modifies how the comparison is made.','grammar'),Q(1,'The suffix -ly turns topographical into…','an adverb','a plural noun','a past participle','Topographically describes the manner or respect of comparison.','word-formation')]);
P('topography','Topography combines Greek topos, “place,” and graphia, “description or writing”; it means the arrangement of landforms or the study and mapping of those features.',[C('topography.s1','地形','The topography here is steep and rocky, so the road follows the river.','这里地势陡峭多岩石，因此道路沿河修建。','rough/varied topography; map the topography','名词，指一个地区山丘、山谷、河流等地表特征的分布。','the relief determines where the road can go.','地形'),C('topography.s2','地形测绘','The course teaches topography and mapmaking for field researchers.','这门课程教授野外研究者地形测绘和制图。','study/teach topography; topography of a region','名词，指测绘或研究地表形态的学科与方法。','students learn to represent land features on maps.','地形测绘')],M('The topography was steep and rocky, but the sentence says the land was perfectly flat with no surface features.','The topography was steep and rocky, with hills and exposed stone shaping the route.','topography指地表形态，平坦无特征与陡峭多岩石相反。','meaning'),[Q(1,'The topography of a region is…','the arrangement of its surface features','its list of current news topics','a layer of paint','Sense 1 is the landform meaning.','meaning'),Q(2,'A topography course teaches…','the study and mapping of land surfaces','how to operate on patients','how to give a legal testimony','Sense 2 is the mapping discipline.','context'),Q(1,'Which phrase is natural?','the topography of the valley','the valley topography ofly','the topography to valleying','Of links the landform description to its region.','grammar'),Q(1,'Greek topos meant…','place','fear','a coat','The compound begins with the Greek word for place.','word-formation')]);
P('toponymy','Toponymy combines Greek topos, “place,” with onyma, “name”; it is the study of place names and the collection of names used in a region.',C('toponymy.s1','地名学','The researcher studies local toponymy to learn how rivers received their old names.','研究者研究当地地名学，以了解这些河流如何得名。','place-name toponymy; study local toponymy','名词，指研究地名来源与使用的学科，也可指一地的地名系统。','the names preserve information about local history.','地名学'),M('The scholar studied toponymy while ignoring every place name and researching animal migration instead.','The scholar studied toponymy by comparing the origins and forms of local place names.','toponymy的研究对象是地名，动物迁徙并非地名学。','meaning'),[Q(1,'Toponymy studies…','place names and how they developed','the surface texture of cloth','the force that turns a shaft','That is the discipline’s subject.','meaning'),Q(1,'What did the researcher learn from river names?','How the rivers received their names','How to apply a topcoat','How an aircraft touches down','The context explicitly concerns name origins.','context'),Q(1,'Which phrase is natural?','local toponymy','toponymy localize','toponymical of localityly','Local modifies the naming system of an area.','collocation'),Q(1,'The Greek parts mean…','place and name','fear and system','ground and coat','Toponymy is the study of names of places.','word-formation')]);
P('topple','Topple is an English verb related to top with an added frequentative -le ending; its origin is not fully certain, and it means fall over or overthrow a leader.',[C('topple.s1','倒下','The stack of books toppled over when the table was bumped.','桌子被撞后，那摞书倒了下来。','topple over; topple from a shelf','动词，指失去平衡而倒下。','the books fall after the stack becomes unstable.','倒下'),C('topple.s2','推翻','Mass protests helped topple the government after months of unrest.','持续数月动荡后，大规模抗议促使政府垮台。','topple a government/leader; help topple a regime','动词，指使领导人或政府失去权力。','protests remove the government from power.','推翻')],M('The stack toppled over but remained perfectly upright and balanced on the table.','The stack toppled over and fell onto the floor.','topple over表示倒下，与保持直立平衡相反。','meaning'),[Q(1,'The stack toppled over means it…','fell after losing balance','became more stable','was covered with soil','Sense 1 is the falling meaning.','meaning'),Q(2,'Protests helped topple the government means they…','helped remove it from power','gave its leader permanent tenure','made the government a tourist attraction','Sense 2 is the political verb.','context'),Q(1,'Which phrase is natural?','topple over','topple under over','over topple to','Over commonly follows topple in the falling sense.','collocation'),Q(1,'Topple is related to…','top, with an English verb-forming -le ending','Greek topos plus name','Latin torque meaning rotate','The form suggests something at the top falling, though the deeper history is uncertain.','word-formation')]);
P('topsoil','Topsoil is a compound of top and soil; it names the fertile upper layer of earth above less productive layers below.',C('topsoil.s1','土壤','Farmers planted cover crops to protect topsoil from wind and heavy rain.','农民种植覆盖作物，防止表层沃土被大风和暴雨侵蚀。','fertile/rich topsoil; erosion of topsoil','名词，指土壤最上层、通常最适于植物生长的部分。','the upper soil layer is protected from erosion.','土壤'),M('The farmer protected the topsoil by scraping away the fertile upper layer and exposing bare rock.','The farmer protected the topsoil by keeping plant cover over the fertile upper layer.','保护topsoil应防止表层土流失，而不是把它刮掉。','meaning'),[Q(1,'Topsoil is…','the fertile upper layer of soil','a protective paint finish','a metal ring worn around the neck','That is the soil-layer sense.','meaning'),Q(1,'Why plant cover crops?','To reduce wind and rain erosion','To make the upper soil disappear','To test a tractor’s torque','The context says plants protect topsoil.','context'),Q(1,'Which phrase is natural?','rich topsoil','topsoil richly upper','soil top in the fertilely','Rich is an adjective describing the soil.','grammar'),Q(1,'Topsoil is formed from…','top and soil','top and coat','top and name','The compound literally identifies the upper soil layer.','word-formation')]);
P('torch','Torch came through Old French torche, a bundle of twisted material used as a light; British English also uses it for a portable electric light, and the verb means set fire deliberately.',[C('torch.s1','手电筒','She shone her torch under the sink to find the leaking pipe.','她用手电筒照水槽下方，寻找漏水的管子。','shine/switch on a torch; torch battery','英式英语名词，指可手持的电池式电灯。','the portable light illuminates a dark space.','手电筒'),C('torch.s2','火把','The guides carried burning torches along the dark path.','向导们沿着昏暗的小路举着燃烧的火把。','carry/light a torch; flaming torch','名词，指一端有燃烧物的长杆火把。','the flame provides light on the path.','火把'),C('torch.s3','纵火','The gang torched the empty warehouse after everyone had left.','所有人离开后，团伙纵火烧了空仓库。','torch a building/car; be torched','动词，指故意放火烧毁某物。','the building is deliberately set alight.','纵火')],M('She shone her torch under the sink, but the torch was a burning stick that set the kitchen alight.','She shone her electric torch under the sink to inspect the pipe.','此处英式torch指手电筒，不是火把，更不是纵火动作。','meaning'),[Q(1,'In British English, a torch under the sink is…','a portable electric light','a school examination','a fast stream','Sense 1 is the British usage.','meaning'),Q(2,'A burning torch carried by guides is…','a flaming stick used as a light','a computer terminal','a body surface cream','Sense 2 is the older firebrand meaning.','context'),Q(3,'The gang torched the warehouse means they…','deliberately set fire to it','painted a protective topcoat','pulled it behind a truck','Sense 3 is the verb.','meaning'),Q(1,'The older torch was a bundle of…','twisted burning material','fertile topsoil','woven legal documents','The original object was a light made from bundled material.','word-formation')]);
P('torment','Torment came through Old French from Latin tormentum, an instrument or process of torture, related to torquere, “twist”; it means prolonged suffering or to cause such suffering.',[C('torment.s1','折磨','He was tormented by memories of the accident for years afterward.','多年以后，他仍被事故的回忆折磨。','be tormented by guilt; torment someone','动词，指长时间造成严重的身体或精神痛苦。','the memories repeatedly cause distress.','折磨'),C('torment.s2','困扰','The same doubt tormented her whenever she had to make a decision.','每当她必须作出决定时，同一个疑虑就困扰着她。','a question/doubt torments someone; torment the mind','动词，指反复使某人烦恼或无法释怀。','the doubt keeps returning to trouble her.','困扰'),C('torment.s3','迫害','The regime tormented members of the religious group because of their beliefs.','该政权因宗教团体成员的信仰而迫害他们。','torment/persecute a group; be tormented for one’s beliefs','动词，指长期残酷、不公地对待某人或某群体。','the group is abused because of its faith.','迫害'),C('torment.s4','痛苦','Waiting for the medical results was a torment for the anxious family.','焦虑的一家人等待检查结果的过程简直是一种折磨。','be a torment; mental/physical torment','名词，指持续而严重的痛苦，或造成痛苦的人或事。','the waiting causes prolonged distress.','痛苦')],M('The recurring doubt tormented her by disappearing forever and never troubling her again.','The recurring doubt tormented her by returning each time she faced a decision.','torment表示反复造成痛苦或困扰，与永不再出现相反。','meaning'),[Q(1,'Memories tormenting him means they…','cause him prolonged mental suffering','help him forget the accident immediately','make a map of the land','Sense 1 is prolonged suffering.','meaning'),Q(2,'A doubt that torments someone…','keeps troubling the person repeatedly','settles the issue once and for all','becomes a protective paint layer','Sense 2 is repeated mental trouble.','context'),Q(3,'The regime tormented a group because of beliefs means it…','treated them cruelly and unfairly over time','gave them a public holiday','invited them to a city tour','Sense 3 is persecution.','meaning'),Q(4,'Waiting was a torment means waiting was…','a source of severe ongoing distress','a pleasant brief rest','a technical map','Sense 4 uses torment as a noun.','meaning')]);
P('tornado','Tornado comes through Spanish tornado/tornear, related to turning; a competing connection is sometimes noted with Spanish tronada, “thunderstorm,” so the exact path is not certain.',[C('tornado.s1','风暴','The tornado tore the roof from the barn and uprooted trees across the field.','龙卷风掀掉谷仓屋顶，并拔倒了田野里的树。','a violent tornado; tornado warning','名词，指旋转猛烈、沿途造成破坏的柱状风暴。','the spinning storm damages structures in its path.','风暴'),C('tornado.s2','大量涌现','A tornado of protest followed the council’s decision to close the library.','议会决定关闭图书馆后，抗议声浪迅速席卷而来。','a tornado of activity/protest; a tornado of emotion','名词，比喻突然猛烈涌现的一大股活动或情绪。','protest arrives suddenly in great force.','大量涌现')],M('The tornado moved gently without rotating and left every roof and tree untouched.','The tornado spun violently and damaged roofs and trees in its path.','tornado是具有旋转风柱并造成破坏的猛烈风暴。','meaning'),[Q(1,'A tornado is…','a violent rotating storm','a lightly warm afternoon breeze','a form of place-name study','That is the weather sense.','meaning'),Q(2,'A tornado of protest means…','a sudden, forceful rush of protest','a single quiet complaint','a circular piece of jewellery','Sense 2 is metaphorical.','context'),Q(1,'Which phrase is natural?','a tornado warning','a warning tornadoingly','tornado of warninged','Tornado warning is the standard compound.','collocation'),Q(1,'One proposed word history connects tornado with…','Spanish words for turning or a thunderstorm','Latin for woven cloth','Hindi for a hat','The Spanish connection is reported with some uncertainty.','word-formation')]);
P('toronto','Toronto is the English name of Ontario’s largest city; one theory traces it to the Mohawk place name Tkarón:to, associated with trees in water, though the city’s name history has several Indigenous-language forms.',C('toronto.s1','地名','She flew to Toronto for a conference on freshwater conservation.','她飞往多伦多参加淡水保护会议。','the city of Toronto; travel to Toronto','专有名词，指加拿大安大略省省会多伦多。','the context identifies a Canadian city.','地名'),M('She flew to Toronto for the conference, a city in Australia on the Indian Ocean.','She flew to Toronto for the conference, the Canadian city on Lake Ontario.','Toronto在此指加拿大安大略省的城市，不是澳大利亚城市。','meaning'),[Q(1,'Toronto is a major city in…','Ontario, Canada','the Australian outback','northern India','The entry identifies it as Ontario’s capital.','meaning'),Q(1,'Why did she travel there?','To attend a freshwater conference','To hike a tortuous trail','To test a topcoat','The example supplies the purpose.','context'),Q(1,'Which capitalization is correct for the city?','Toronto','toronto','TORONTO is required in every sentence','Proper place names begin with a capital letter.','capitalization'),Q(1,'One proposed Indigenous-language source, Tkarón:to, is associated with…','trees in water','a twisted metal collar','a feeling of extreme fear','The City of Toronto presents this as one theory, not a settled certainty.','word-formation')]);
P('torpid','Torpid comes from Latin torpidus, “numb or sluggish,” from torpere, “be numb”; it describes low physical or mental activity and animals inactive during winter.',[C('torpid.s1','迟钝无力','The heat left the hikers torpid after lunch, and they rested in the shade.','午饭后炎热天气让徒步者昏沉乏力，他们便在阴凉处休息。','feel/lie torpid; torpid with heat','形容词，指身心不活跃、缺乏精力的。','the hikers have little energy after the heat.','迟钝无力'),C('torpid.s2','冬眠状态','Some insects remain torpid through the cold months and become active again in spring.','有些昆虫在寒冷月份保持蛰伏状态，春天才重新活动。','torpid through winter; remain torpid','形容词，指动物在冬眠或寒季期间不活跃的状态。','the insects are seasonally inactive.','冬眠状态')],M('The heat left the hikers torpid, so they ran energetically up the hill without resting.','The heat left the hikers torpid, so they rested in the shade.','torpid表示缺少活力，与精力充沛地奔跑相反。','meaning'),[Q(1,'Torpid hikers are…','inactive and low in energy','very energetic and restless','covered in a textile','Sense 1 is sluggishness.','meaning'),Q(2,'Insects torpid through winter are…','inactive during the cold season','active only at noon','travelling on a tour','Sense 2 is seasonal animal inactivity.','context'),Q(1,'Which phrase is natural?','remain torpid through winter','remain torpidly winter through','winter torpid of remain','Through marks the period of inactivity.','collocation'),Q(1,'Latin torpere meant…','to be numb or sluggish','to name a place','to give thanks','Torpid descends from the Latin state of numbness.','word-formation')]);
P('torpor','Torpor comes from Latin torpor, from torpere, “be numb”; it names physical or mental sluggishness and seasonal inactivity in some animals.',[C('torpor.s1','倦怠','A heavy lunch and the hot room induced a general torpor in the class.','丰盛的午餐和闷热教室使全班普遍昏昏欲睡。','fall into torpor; mental/physical torpor','名词，指身心迟钝、缺乏活力的状态。','students become sluggish after eating in the heat.','倦怠'),C('torpor.s2','蛰伏','The dormouse passes the winter in torpor and wakes when the weather warms.','睡鼠冬天处于蛰伏状态，天气转暖后才醒来。','winter torpor; a period of torpor','名词，指某些动物寒季不活动的状态。','the animal remains inactive during winter.','蛰伏')],M('The class fell into torpor, meaning everyone became alert, energetic, and eager to run.','The class fell into torpor, with students struggling to stay alert after lunch.','torpor是迟钝无力的状态，不是警觉且精力充沛。','meaning'),[Q(1,'A class in torpor is…','sluggish and low in energy','fully alert and active','receiving a permanent job','Sense 1 is mental or physical sluggishness.','meaning'),Q(2,'A dormouse in winter torpor is…','inactive during the cold season','mapping a region','taking a warm shower','Sense 2 is animal inactivity.','context'),Q(1,'Which phrase is natural?','a period of torpor','a torpor periodly','torpor of perioded','Period of torpor is a natural noun phrase.','collocation'),Q(1,'Torpor is related to Latin torpere, meaning…','to be numb or sluggish','to turn a wheel','to give a speech','The Latin root describes reduced sensation or activity.','word-formation')]);
P('torque','Torque is from Latin torquere, “to twist”; in mechanics it is a turning effect of force, while a torque is also an ancient twisted metal neck ring.',[C('torque.s1','力矩','The diesel engine produces high torque at low speed, helping the truck climb the hill.','柴油发动机在低转速下能产生较大扭矩，帮助卡车爬坡。','engine torque; apply/measure torque','名词，指使物体绕轴转动的力矩。','the turning effect helps rotate the wheels.','力矩'),C('torque.s2','颈环','The museum displayed a gold torque found in an ancient burial.','博物馆展出了一件古墓中发现的金质扭颈环。','a gold/bronze torque; twisted metal torque','名词，指古代文化中佩戴的扭绞金属项圈。','the artifact is a twisted neck ornament.','颈环')],M('The engine’s torque was its flat woven scarf worn around the driver’s neck.','The engine’s torque was the turning force that helped rotate its wheels.','机械学中torque指旋转效应，不是颈饰；两词另有古代饰物义。','meaning'),[Q(1,'Engine torque describes…','the turning effect of a force','the vehicle’s paint layer','its speed limit only','Sense 1 is the mechanical quantity.','meaning'),Q(2,'The gold torque in the museum was…','a twisted metal neck ring','a computer trackpad','a type of crop soil','Sense 2 is the ancient ornament.','context'),Q(1,'Which phrase is natural?','apply torque to the bolt','apply the bolt torqueingly','torque of applyingly bolt','Torque can be applied to turn a fastener.','collocation'),Q(1,'Latin torquere meant…','to twist','to map a place','to be numb','The verb is the source of both turning and twisted-object senses.','word-formation')]);
P('torrent','Torrent comes from Latin torrentem, “rushing or boiling,” from torrere, “scorch”; it means a violent stream of water or a sudden, overwhelming amount of something.',[C('torrent.s1','急流','A torrent of rainwater rushed down the gorge after the storm.','暴雨过后，一股急流沿峡谷奔腾而下。','a torrent of water; mountain torrent','名词，指水量大、流速快且可能带有破坏力的水流。','the water moves quickly through the gorge.','急流'),C('torrent.s2','大量涌来','She faced a torrent of criticism after the interview was broadcast.','采访播出后，她遭到大量批评。','a torrent of criticism/abuse/questions; pour in a torrent','名词，比喻突然大量涌现的言语、情绪或事物。','many critical comments arrive in a short time.','大量涌来')],M('A torrent of criticism arrived as one quiet, isolated comment over several years.','A torrent of criticism arrived in a sudden, overwhelming stream after the broadcast.','torrent比喻短时间内大量涌来的批评，不是多年间零星一句。','meaning'),[Q(1,'A water torrent is…','a fast, powerful stream','a slow dry path','a textile fibre','Sense 1 describes rushing water.','meaning'),Q(2,'A torrent of criticism means…','a sudden large amount of criticism','one mild comment','a metal torque','Sense 2 uses torrent figuratively.','context'),Q(1,'Which phrase is natural?','a torrent of questions','a torrent questionsly of','questions torrenting to','Of introduces what arrives in the large amount.','grammar'),Q(1,'Latin torrentem described something…','rushing or boiling','slowly becoming numb','being held permanently','The English word preserves an image of rushing flow.','word-formation')]);
P('torrential','Torrential is formed from torrent with -ial; it describes rain falling extremely heavily or water moving with the force of a torrent.',C('torrential.s1','暴雨','Torrential rain flooded the underpass before the drains could carry it away.','排水系统还没来得及排走，倾盆大雨就淹没了地下通道。','torrential rain/downpour; torrential flow','形容词，指雨下得极大，或水流奔腾猛烈的。','the rain arrives heavily enough to flood a low road.','暴雨'),M('Torrential rain fell as a few light drops that barely wet the pavement.','Torrential rain fell heavily and flooded the underpass.','torrential表示极其猛烈或大量的降雨，不是稀疏小雨。','meaning'),[Q(1,'Torrential rain is…','very heavy rain','a light mist','rain that never reaches the ground','That is the adjective’s weather sense.','meaning'),Q(1,'What happened during the torrential rain?','The underpass flooded','The road dried instantly','The engine produced torque','The context shows the rain was intense.','context'),Q(1,'Which phrase is natural?','torrential downpour','downpour torrentially','a torrentially of rain','Torrential is an adjective modifying downpour.','grammar'),Q(1,'Torrential is formed from…','torrent plus -ial','torrid plus -ness','topography plus -ical','The suffix forms an adjective related to a torrent.','word-formation')]);
P('torrid','Torrid comes from Latin torridus, “parched or scorched,” from torrere, “dry by heat”; it describes very hot climates and, figuratively, passionate or intense matters.',[C('torrid.s1','炎热','The hikers crossed the torrid plateau at night to avoid the daytime heat.','徒步者夜间穿越酷热的高原，以避开白天的高温。','torrid climate/heat; torrid summer','形容词，指天气或气候非常炎热、干燥的。','they travel at night to avoid scorching conditions.','炎热'),C('torrid.s2','热烈','The novel leaves out the couple’s torrid correspondence but hints at their intense affair.','小说没有呈现两人的炽热通信，却暗示了他们热烈的恋情。','torrid affair/romance; torrid relationship','形容词，指感情强烈、热情奔放的，有时带有情色意味。','their letters reveal passionate emotions.','热烈')],M('The torrid plateau was freezing and damp throughout the summer.','The torrid plateau was extremely hot and dry during the day.','torrid描述酷热干燥，与整夏寒冷潮湿相反。','meaning'),[Q(1,'A torrid plateau is…','extremely hot, often dry','cold and wet','covered with fertile topsoil','Sense 1 is the climate use.','meaning'),Q(2,'A torrid correspondence suggests…','intense passion or emotion','neutral business notices only','a legal trial','Sense 2 is figurative and emotional.','context'),Q(1,'Which phrase is natural?','a torrid summer','a summer torridlyly','torridness summer of','Torrid is an adjective before summer.','grammar'),Q(1,'Latin torrere meant…','to parch or dry with heat','to twist a metal collar','to name a place','The original heat sense remains in torrid climate.','word-formation')]);
P('torsion','Torsion comes through French from Latin torsio, from torquere, “to twist”; it is the twisting of an object or the stress produced by that twist.',C('torsion.s1','力学','The metal shaft failed under torsion when the motor suddenly reversed direction.','电机突然反转时，金属轴在扭转载荷下断裂。','torsion stress; resist/measure torsion','名词，指物体一端相对另一端转动造成的扭转或由此产生的应力。','the shaft is twisted around its axis.','力学'),M('The shaft failed under torsion because it was compressed straight along its length and never twisted.','The shaft failed under torsion because opposing forces twisted it around its axis.','torsion指扭转作用，而不是单纯沿长度方向受压。','meaning'),[Q(1,'A shaft under torsion is…','being twisted around an axis','being coated with paint','being pulled behind a truck','That is the mechanical sense.','meaning'),Q(1,'What caused the shaft to fail?','The motor reversed and twisted it','A flock of tortoises crossed it','A topcoat dried on it','The context identifies a twisting load.','context'),Q(1,'Which phrase is natural?','torsion stress','stress torsionly','a torsion of stresses','Torsion stress names stress caused by twisting.','collocation'),Q(1,'Latin torquere meant…','to twist','to give thanks','to name a place','Torsion belongs to the Latin family built on twisting.','word-formation')]);
P('tortoise','Tortoise entered English through French tortue/tortre for a turtle; the French word’s deeper origin is unknown, so no certain root is claimed.',C('tortoise.s1','动物','The tortoise withdrew its legs into its hard shell when the dog approached.','狗靠近时，陆龟把四肢缩进坚硬的壳里。','land tortoise; tortoise shell','名词，指行动缓慢、具有可缩入硬壳的陆生动物。','the animal protects itself by withdrawing into its shell.','动物'),M('The tortoise withdrew its legs into its shell to expose itself to the dog.','The tortoise withdrew its legs into its shell to protect itself from the dog.','缩入硬壳是陆龟的防御行为，不是为了暴露自己。','meaning'),[Q(1,'A tortoise is a…','slow-moving land animal with a hard shell','bird that dives for fish','small portable light','That matches the source definition.','meaning'),Q(1,'How did the tortoise react to the dog?','It withdrew into its shell','It flew to Toronto','It applied a topcoat','The example describes the animal’s defensive action.','context'),Q(1,'Which phrase is natural?','a land tortoise','a tortoise of landly','a shell tortoise into','Land identifies this kind of shelled animal.','collocation'),Q(1,'The French source tortue has…','an uncertain deeper origin','a certain meaning “to weave”','a known meaning “thankfulness”','The deeper history is not established, so it should not be invented.','word-formation')]);
P('tortuous','Tortuous comes from Latin tortuosus, “winding,” from tortus, “twisted”; it describes a path with many turns or an argument that is long and hard to follow.',C('tortuous.s1','曲折','The tortuous path followed the cliff edge through a series of sharp turns.','这条蜿蜒小路沿着悬崖边经过一连串急转弯。','tortuous road/path; a tortuous route','形容词，指道路弯曲、曲折多转的。','the path winds rather than taking a straight line.','曲折'),M('The tortuous path ran straight across the field with no bends or turns.','The tortuous path wound around the cliff through many turns.','tortuous表示弯曲复杂，与笔直无弯相反。','meaning'),[Q(1,'A tortuous path is…','winding and full of turns','straight and direct','a fertile soil layer','That is the literal sense.','meaning'),Q(1,'Where did the path go?','Along the cliff edge','Across a flat painted wall','Through the center of a theater stage','The example says it follows the cliff through turns.','context'),Q(1,'Which phrase is natural?','a tortuous route','a tortuously route','route tortuousnessly','Tortuous is an adjective modifying route.','grammar'),Q(1,'The Latin source tortus meant…','twisted','grateful','the whole','The root’s twisting image explains the winding sense.','word-formation')]);
P('torture','Torture came through Old French from Latin tortura, “a twisting or torment,” from torquere, “twist”; it names severe suffering or the act of causing it deliberately.',[C('torture.s1','施刑','The report described the torture of prisoners by guards seeking information.','报告描述了看守为获取信息而对囚犯施加的酷刑。','inflict/ban torture; torture of prisoners','名词，指为了惩罚或逼供而故意造成的严重痛苦。','the pain is inflicted to punish or obtain information.','施刑'),C('torture.s2','煎熬','Waiting for the test results was torture for the worried family.','焦急的一家人等待检查结果时备受煎熬。','be torture; mental/physical torture','名词，指严重的身心痛苦。','the long wait causes intense distress.','煎熬'),C('torture.s3','折磨','Guilt tortured him for years after he ignored the warning.','他忽视警告后，多年来一直受到愧疚折磨。','torture someone with guilt; be tortured by pain','动词，指故意使人承受严重疼痛或精神痛苦。','guilt causes lasting psychological suffering.','折磨')],M('The guards tortured the prisoner by ensuring he felt no pain and experienced no distress.','The guards tortured the prisoner by deliberately inflicting severe pain.','torture意味着故意造成严重痛苦，与确保毫无痛苦相反。','meaning'),[Q(1,'Torture of prisoners refers to…','deliberately inflicting severe pain','giving them a tour of the city','applying topical cream','That is the serious noun sense.','meaning'),Q(2,'Waiting for results was torture means it was…','extremely distressing','a pleasant short break','a game with a winner','Sense 2 is figurative suffering.','context'),Q(3,'Guilt tortured him means guilt…','caused him prolonged mental suffering','helped him forget the warning','gave him a permanent post','Sense 3 is the verb.','meaning'),Q(1,'Latin torquere meant…','to twist','to total a bill','to write a place description','The historical root is associated with twisting or turning.','word-formation')]);
P('torturous','Torturous is formed from torture with -ous; it describes an experience that causes prolonged physical pain or is unpleasantly long and difficult to bear.',[C('torturous.s1','疼痛','He endured a torturous recovery after the operation, with pain each time he moved.','手术后他经历了痛苦漫长的恢复期，每次移动都会疼痛。','torturous recovery/pain; torturous injury','形容词，指造成持续而剧烈身体痛苦的。','movement repeatedly causes pain.','疼痛'),C('torturous.s2','难熬','The meeting turned into a torturous three-hour debate over one sentence.','会议变成了一场围绕一句话持续三小时的难熬辩论。','torturous wait/meeting; a torturous process','形容词，指漫长而令人难以忍受的。','the debate drags on unpleasantly.','难熬')],M('The torturous three-hour meeting was short, painless, and over in five minutes.','The torturous meeting lasted three unpleasant hours.','torturous表示难以忍受且漫长，与短暂轻松相反。','meaning'),[Q(1,'A torturous recovery is…','physically painful over time','effortless and painless','a topographical survey','Sense 1 concerns physical pain.','meaning'),Q(2,'A torturous meeting is…','unpleasantly long and difficult to bear','a quick enjoyable chat','a river carrying fast water','Sense 2 is the figurative use.','context'),Q(1,'Which phrase is natural?','a torturous wait','a torturously wait','wait torturousness to','Torturous is an adjective modifying wait.','grammar'),Q(1,'Torturous is formed from…','torture plus -ous','total plus -ity','touch plus -down','The suffix makes an adjective meaning full of or causing torture.','word-formation')]);
P('toss','Toss is a verb of uncertain origin, possibly from a Scandinavian source; it means throw lightly, jerk the body, flip a coin, or the act of throwing.',[C('toss.s1','轻抛','Toss me the keys when you reach the doorway.','你走到门口时把钥匙轻轻抛给我。','toss someone the keys; toss a ball','动词，指轻轻或随手把东西扔给某人。','the keys are thrown a short distance.','轻抛'),C('toss.s2','猛动','She tossed her hair and walked away without answering.','她甩了甩头发，没有回答便走开了。','toss one’s head/hair; toss and turn','动词，指突然甩动头、头发或身体。','the movement is sudden and expressive.','猛动'),C('toss.s3','掷硬币','Let us toss a coin to decide who serves first.','我们掷硬币决定谁先发球吧。','toss a coin; win/lose the toss','动词，指把硬币抛起以随机决定事情。','the coin chooses between two options.','掷硬币'),C('toss.s4','抛掷/掷币','She won the toss and chose to serve first.','她赢得掷硬币的选择权，决定先发球。','win/lose the toss; a toss of a coin','名词，指轻抛动作或决定先后的掷硬币。','the coin toss determines the choice.','抛掷/掷币')],M('He tossed the keys to me by placing them carefully on a shelf across the room.','He tossed the keys to me with a light throw.','toss是轻轻抛掷，不是远处放置。','meaning'),[Q(1,'“Toss me the keys” asks someone to…','throw the keys lightly to me','hide the keys in the soil','trade the keys for a tractor','Sense 1 is a light throw.','meaning'),Q(2,'She tossed her hair means she…','moved it suddenly with a quick motion','wove it into a topcoat','tested it for toxins','Sense 2 is a physical movement.','context'),Q(3,'To toss a coin is to…','flip it into the air to decide something','paint it with a topcoat','tow it behind a truck','Sense 3 describes a decision method.','meaning'),Q(4,'Winning the toss means winning…','the coin flip used to decide who starts','the tournament itself','a city tour','Sense 4 is the noun for that decision toss.','context')]);
P('total','Total comes through French from Medieval Latin totalis, from totus, “whole”; it can be the complete sum, an adjective meaning complete, or a verb meaning add up to.',[C('total.s1','总数','The total is forty after the three receipt amounts are added.','把三张收据上的金额相加后，总数是四十。','grand/overall total; calculate a total','名词，指把各部分加在一起得到的数额。','the individual amounts are summed.','总数'),C('total.s2','全部的','The trip was a total success despite the rain on the first day.','尽管第一天下雨，这次旅行还是完全成功。','total failure/silence; total control','形容词，指完整的、包括一切的。','the success is complete, not partial.','全部的'),C('total.s3','总计','The four invoices total two hundred yuan.','四张发票合计两百元。','costs total; total an amount','动词，指加起来达到某个数字。','the invoices add up to the stated amount.','总计')],M('The four invoices total 200 yuan, meaning their combined sum is only 20 yuan.','The four invoices total 200 yuan when their amounts are added together.','total作为动词表示合计，原句却给出了不同的合计数。','meaning'),[Q(1,'The total on the receipts is…','the sum after adding the amounts','one receipt selected at random','a word used in a subject','Sense 1 is the noun sum.','meaning'),Q(2,'A total success is…','a complete success','a partial failure','a slightly warm response','Sense 2 means complete.','context'),Q(3,'The invoices total 200 yuan means…','their amounts add up to 200 yuan','each invoice costs 200 yuan','the total is unknown','Sense 3 is the verb meaning add up to.','meaning'),Q(1,'Latin totus meant…','whole or all','to twist','to be numb','The root explains total’s complete or sum meanings.','word-formation')]);
P('totalitarian','Totalitarian was formed in English on the model of Italian totalitario, from total plus an ending modeled on authoritarian; it describes a political system seeking total control and suppressing opposition.',C('totalitarian.s1','政治制度','The country lived under a totalitarian regime that banned opposition parties and censored the press.','该国处于一个禁止反对党并审查媒体的极权政权统治之下。','totalitarian state/regime; totalitarian control','形容词，指由一党或领袖实行全面控制、不允许反对的政治制度。','the government restricts political and social opposition.','政治制度'),M('The totalitarian regime protected free opposition parties and allowed the press to criticize it without restriction.','The totalitarian regime banned opposition parties and censored criticism.','totalitarian政体追求全面控制并压制反对，与保护自由反对党相反。','meaning'),[Q(1,'A totalitarian regime…','seeks total control and forbids opposition','holds open elections with unrestricted opposition','is a type of local government office','That is the political meaning.','meaning'),Q(1,'What did the regime do in the example?','Banned opposition parties and censored the press','Encouraged every newspaper to criticize it','Held a tournament','The context names forms of political control.','context'),Q(1,'Which phrase is natural?','a totalitarian regime','a regime totalitarianlyness','totalitarian to the regime','Totalitarian is an adjective modifying regime.','grammar'),Q(1,'The English word was modeled on Italian…','totalitario','topi','torpore','The adjective entered English using the Italian political term as a model.','word-formation')]);
P('totalitarianism','Totalitarianism is formed from totalitarian plus -ism, a suffix naming a system or doctrine; it refers to government seeking unlimited authority over society.',C('totalitarianism.s1','政治制度','The novel depicts life under totalitarianism, where one ideology controls public and private life.','这部小说描写了极权主义之下的生活：一种意识形态控制着公共与私人生活。','rise/resist totalitarianism; a system of totalitarianism','名词，指一党或一种意识形态试图全面控制社会的政体或制度。','authority extends through many parts of social life.','政治制度'),M('The novel depicts totalitarianism as a system that protects unrestricted political opposition and limits government power.','The novel depicts totalitarianism as a system that suppresses opposition and expands state control.','totalitarianism指追求无限权力的控制制度，而不是限制政府权力。','meaning'),[Q(1,'Totalitarianism is…','a system seeking unlimited control over society','a democratic rule with unrestricted opposition','a study of place names','That is the political noun meaning.','meaning'),Q(1,'What controls life in the novel?','One ideology','A flock of animals','A series of map contours','The example says one ideology controls public and private life.','context'),Q(1,'Which phrase is natural?','resist totalitarianism','totalitarianism resistly','resist to totalitarianisming','Resist takes the system as its direct object.','grammar'),Q(1,'The suffix -ism commonly names…','a system or doctrine','a person who performs an action','a location for a performance','Totalitarianism names the political system or ideology.','word-formation')]);
P('totality','Totality comes from Latin totalitas, “wholeness,” from totalis; it means the whole extent of something and also the phase of a solar eclipse when the sun is fully obscured.',[C('totality.s1','整体','The report must be read in its totality before the findings are summarized.','总结研究结果前，必须通读报告全文。','in its totality; the totality of evidence','名词，指某事物的全部范围或整体。','the reader should consider every part together.','整体'),C('totality.s2','日全食','The observers travelled north to see totality during the solar eclipse.','观测者向北旅行，以观看日食期间的全食阶段。','eclipse totality; enter/reach totality','名词，指日全食中月亮完全遮住太阳的阶段。','the sun is fully hidden at that phase.','日全食')],M('The report was considered in its totality after the reviewers read only one sentence and ignored all remaining sections.','The report was considered in its totality after the reviewers read every section.','in its totality要求考虑整体，而不是只读一句便忽略其余内容。','meaning'),[Q(1,'Read in its totality means read…','as a whole, including all parts','only the opening sentence','after it has been shortened to one page','Sense 1 is the whole-extent meaning.','meaning'),Q(2,'During eclipse totality…','the moon completely hides the sun','the moon is not visible at all times','the sun becomes a planet','Sense 2 is the astronomical phase.','context'),Q(1,'Which phrase is natural?','the totality of the evidence','the evidence totalityly of','the totality to evidence','Of links the whole to its parts.','grammar'),Q(1,'Latin totalitas meant…','wholeness or the whole state','violent twisting','political opposition','Totality names completeness.','word-formation')]);
P('totally','Totally is formed from total plus -ly; it means completely or in every way, often modifying an adjective or verb.',C('totally.s1','完全','I totally agree with your plan to keep the old bridge open during repairs.','我完全赞同你在维修期间保留旧桥通行的计划。','totally agree/disagree; totally different','副词，指完全地、彻底地或在所有方面。','the speaker’s agreement is complete.','完全'),M('I totally agree with your plan means I disagree with it in every possible way.','I totally agree with your plan means I agree with it completely.','totally agree表示完全赞同，不能解释为完全反对。','meaning'),[Q(1,'Totally agree means…','agree completely','disagree slightly','end a contract','That is the adverb’s meaning.','meaning'),Q(1,'What does the speaker support?','Keeping the bridge open during repairs','Closing every road permanently','Changing the town’s name','The example states the plan directly.','context'),Q(1,'Which sentence is natural?','I totally agree with the plan.','I totally agreement with the plan.','I agree totallyly the plan.','Totally modifies the verb agree.','grammar'),Q(1,'The suffix -ly turns total into…','an adverb','a plural noun','a comparative conjunction','Totally describes the extent of agreement.','word-formation')]);
P('totemism','Totemism combines totem with -ism; totem entered English through an Algonquian language, often identified as Ojibwe, and refers to kinship or ritual systems linking a group with an emblematic being.',C('totemism.s1','人类学','The lecture compared forms of totemism in which clans were linked to animal emblems.','讲座比较了不同形式的图腾制度，其中氏族与动物象征相联系。','study of totemism; clan totemism','名词，指氏族与某种动物、植物或象征性存在相联系的亲属与仪式体系。','the emblem marks kinship and ritual identity.','人类学'),M('The lecture described totemism as a system with no connection between clans, rituals, or emblems.','The lecture described totemism as a system linking clans with emblems and rituals.','totemism的核心正是群体、象征物和仪式之间的联系。','meaning'),[Q(1,'Totemism can link a clan with…','an animal or plant emblem','a bus terminal','a political campaign poster only','That is the anthropological sense.','meaning'),Q(1,'What did the lecture compare?','Different clan systems linked to animal emblems','Different kinds of paint topcoat','Ways to send a text','The context identifies the systems under study.','context'),Q(1,'Which phrase is natural?','a study of totemism','a totemism studyingly','totemism with the study ofly','A study of introduces the field being examined.','grammar'),Q(1,'The suffix -ism here names…','a system or practice','a person who performs an action','a direction toward a place','Totemism names a social and ritual system.','word-formation')]);
P('touch','Touch comes through French toucher; its deeper origin is uncertain. It means make contact, move someone emotionally, briefly discuss a subject, the sense of feeling, or a small amount/detail.',[C('touch.s1','接触','Do not touch the wet paint until the warning sign is removed.','警示牌撤掉前不要碰未干的油漆。','touch the surface; do not touch','动词，指用手或物体碰到某人或某物。','the hand must stay off the wet surface.','接触'),C('touch.s2','感动','The letter touched me deeply because it remembered a small kindness from years ago.','那封信记得多年前一件小善举，让我深受感动。','be touched by kindness; touch someone emotionally','动词，指使某人产生同情、感激或悲伤等情感。','the remembered kindness moves the reader.','感动'),C('touch.s3','简要谈及','The report touches on costs but gives no detailed budget.','报告简要谈到成本，但没有列出详细预算。','touch on a subject; briefly touch upon an issue','动词，指简略地涉及某个主题。','the report mentions costs only briefly.','简要谈及'),C('touch.s4','触觉','The fabric feels soft to the touch but remains strong when wet.','这种布料摸起来柔软，但遇水仍很结实。','soft/smooth to the touch; sense of touch','名词，指触摸时的感觉或触觉。','the phrase describes how the fabric feels.','触觉'),C('touch.s5','少量/点缀','Add a touch of lemon to brighten the soup.','加一点柠檬能让汤的味道更清新。','a touch of salt/humour; add a touch','名词，指少量某物或提升效果的小细节。','a small amount changes the flavour.','少量/点缀')],M('The report touched on costs by devoting every page to a detailed budget and nothing else.','The report touched on costs briefly but left out a detailed budget.','touch on表示简略提及，不是详尽讨论。','meaning'),[Q(1,'Do not touch the wet paint means…','do not put a hand or object against it','read the report’s entire budget','add a large amount of lemon','Sense 1 is physical contact.','meaning'),Q(2,'The letter touched me means it…','moved me emotionally','made physical contact with my hand','briefly mentioned a budget','Sense 2 is emotional effect.','context'),Q(3,'The report touches on costs means it…','mentions costs briefly','covers costs in exhaustive detail','touches the printed page','Sense 3 means deal with a topic briefly.','meaning'),Q(5,'A touch of lemon is…','a small amount of lemon','a complete lemon harvest','a type of tactile sensation','Sense 5 is a small quantity or detail.','context')]);
P('touch down','Touch down combines touch with down; it means an aircraft lands, or in American football a player scores by carrying the ball into the opposing end zone.',[C('touch down.s1','着陆','The plane touched down ten minutes late because the runway was covered in rain.','由于跑道湿滑，飞机晚了十分钟着陆。','touch down safely; touch down at an airport','短语动词，指飞机降落并接触地面。','the aircraft reaches the runway.','着陆'),C('touch down.s2','美式橄榄球','The team touched down twice in the second half to win the game.','球队在下半场达阵两次，赢得比赛。','touch down in the end zone; score a touchdown','短语动词，在美式橄榄球中指持球进入对方端区得分。','the team scores by reaching the end zone.','美式橄榄球')],M('The plane touched down by climbing away from the runway and staying in the air.','The plane touched down when its wheels met the runway.','飞机touch down表示着陆，离开跑道升空正好相反。','meaning'),[Q(1,'The plane touched down means it…','landed on the runway','took off into the sky','reached a study topic','Sense 1 is the aircraft phrasal verb.','meaning'),Q(2,'The team touched down twice means it…','scored two times in American football','landed two aircraft','lost the coin toss twice','Sense 2 is the sports scoring use.','context'),Q(1,'Which phrase is natural?','the plane touched down safely','the plane touched down into air','the plane down touchedly','Down follows touch in the landing expression.','grammar'),Q(1,'Touch down is a…','verb plus particle forming a phrasal verb','noun plus an adjective ending','compound for a paint layer','The phrasal verb combines contact with downward motion.','word-formation')]);
P('touchdown','Touchdown combines touch and down; it names the landing of an aircraft or spacecraft and a scoring play in American and Canadian football.',[C('touchdown.s1','航空','The spacecraft’s touchdown was smooth despite the crosswind on the landing plain.','尽管着陆平原有侧风，航天器还是平稳着陆。','aircraft/spacecraft touchdown; make a touchdown','名词，指飞机或航天器飞行结束时接触地面的动作。','the vehicle reaches the ground at the end of flight.','航空'),C('touchdown.s2','橄榄球','The quarterback threw a touchdown in the final minute, securing the win.','四分卫在最后一分钟传球达阵，锁定了胜局。','score/throw a touchdown; touchdown pass','名词，指美式或加拿大式橄榄球中将球带入或传入端区而得的六分。','the play puts the ball into the end zone.','橄榄球')],M('The spacecraft’s touchdown happened while it remained high above the ground and never landed.','The spacecraft’s touchdown happened when it reached and contacted the ground.','touchdown的航空义指飞行器接触地面，不是仍在高空。','meaning'),[Q(1,'An aircraft touchdown is…','the act of reaching the ground at landing','the takeoff before a flight','a theatre performance','Sense 1 is the landing noun.','meaning'),Q(2,'A touchdown pass is part of…','American or Canadian football','a city walking tour','a laboratory test','Sense 2 is the sports score.','context'),Q(1,'Which phrase is natural?','make a smooth touchdown','touchdown a make smoothly','smoothly touchdowning make','Make a touchdown is a common noun phrase.','collocation'),Q(1,'Touchdown is formed from…','touch and down','total and -ity','torture and -ous','The compound names contact with the ground.','word-formation')]);
P('touched','Touched is the past participle of touch used as an adjective; it means emotionally moved, and informally or dated it can mean slightly eccentric.',[C('touched.s1','感动','I was touched by their letter thanking me for the help I had almost forgotten.','他们写信感谢我那件几乎已忘记的小忙，我很受感动。','be touched by kindness; feel touched','形容词，指受到善意或感人之事触动的。','the letter causes a warm emotional response.','感动'),C('touched.s2','略显古怪','In the old comedy, the neighbours jokingly call the eccentric inventor a little touched.','在那部老喜剧里，邻居们开玩笑说那位古怪发明家有点不正常。','a bit/slightly touched (informal, dated)','形容词，旧式或非正式用法，指行为略显古怪。','the phrase is a dated informal characterization, not a diagnosis.','略显古怪')],M('I was touched by the kind letter, meaning it left me completely unmoved and indifferent.','I was touched by the kind letter and felt grateful for its thoughtfulness.','be touched by表示被感动，原句解释成毫无触动正好相反。','meaning'),[Q(1,'“I was touched by their letter” means I was…','emotionally moved','physically injured','unaware that a letter existed','Sense 1 is the emotional use.','meaning'),Q(2,'In old informal speech, “a little touched” can mean…','slightly eccentric','deeply grateful','formally appointed','Sense 2 is dated and informal.','context'),Q(1,'Which phrase is natural?','touched by their kindness','touched from their kindly','their kindness touchedly by','By introduces the cause of the feeling.','grammar'),Q(1,'Touched is the past participle of…','touch','tour','toughen','The adjective derives from the participle form of touch.','word-formation')]);
P('touching','Touching is the -ing form of touch used adjectivally for something emotionally moving; in the expression touching on, it means concerning or relating to a topic.',[C('touching.s1','感人','It was a touching farewell speech that brought several listeners to tears.','这场感人的告别演讲让几位听众流下了眼泪。','a touching story/scene; deeply touching','形容词，指引起温暖、怜悯或同情等情感的。','listeners are emotionally affected.','感人'),C('touching.s2','关于','The talk was touching on the town’s industrial history when the alarm interrupted it.','警报打断演讲时，演讲正谈到小镇的工业史。','touching on a subject; a point touching on policy','介词性用法，指涉及或谈到某个主题。','the talk has begun to discuss that subject.','关于')],M('The touching farewell speech moved no one and caused every listener to feel nothing.','The touching farewell speech moved several listeners to tears.','touching描述能引起情感反应的事物，与完全不感人相反。','meaning'),[Q(1,'A touching speech is…','emotionally moving','a technical map of a town','a vehicle pulled behind a truck','Sense 1 is the adjective.','meaning'),Q(2,'The talk was touching on history means it was…','discussing or relating to that subject','physically touching a history book only','ending the town’s history','Sense 2 is the topic-related phrase.','context'),Q(1,'Which phrase is natural?','a touching farewell','a farewell touchinglyly','a touchingly farewell','Touching is an adjective modifying farewell.','grammar'),Q(1,'In “touching on history,” touching on means…','concerning or discussing briefly','landing on a runway','emotionally moving every listener','The phrase introduces the subject discussed.','meaning')]);
P('touchy','Touchy is formed from touch plus -y; it describes a person easily offended by small remarks or a subject needing careful handling.',[C('touchy.s1','易生气','He is touchy about his accent, so the interviewer avoided teasing him about it.','他对自己的口音很敏感，因此采访者没有拿这件事打趣。','touchy about a subject; a touchy person','形容词，指容易因小事感到受冒犯或不快的。','the interviewer avoids a remark that could upset him.','易生气'),C('touchy.s2','棘手敏感','Pay is a touchy subject in the office, so the manager discussed it privately.','薪酬是办公室里的敏感话题，所以经理私下讨论。','a touchy issue/question; touchy subject','形容词，指处理不慎可能引起麻烦或不快的议题。','talking about salaries could cause conflict.','棘手敏感')],M('He was touchy about his accent, so he welcomed every joke and never felt offended.','He was touchy about his accent, so he felt offended by jokes about it.','touchy指容易被冒犯，与从不介意嘲笑相反。','meaning'),[Q(1,'A touchy person is…','easily upset by small remarks','always impossible to offend','a person who sells goods','Sense 1 describes sensitivity.','meaning'),Q(2,'Pay is a touchy subject because…','careless discussion may cause conflict','no one ever has an opinion about pay','it is a type of physical texture','Sense 2 is a sensitive issue.','context'),Q(1,'Which phrase is natural?','touchy about his accent','touchy of his accently','his accent touchy to about','About introduces what the person is sensitive about.','grammar'),Q(1,'The suffix -y in touchy forms…','an adjective meaning characterized by touchiness','a noun meaning a job','a verb meaning to tow','Touchy describes a person or issue prone to sensitivity.','word-formation')]);
P('tough','Tough comes from Old English toh, “strong or firm”; it means difficult, durable, strict or resilient, and hard to cut or chew.',[C('tough.s1','困难','It was a tough decision to close the family shop after so many years.','经营多年后决定关闭家族商店，实在是个艰难的决定。','a tough choice/task; tough to do','形容词，指难以处理或完成的。','the decision has emotional and practical difficulty.','困难'),C('tough.s2','坚韧','This tough plastic case protects the camera when it is dropped.','这种坚韧的塑料外壳能在相机掉落时保护它。','tough material/skin; tough enough to withstand','形容词，指坚固、不易破裂或损坏的。','the case resists impact.','坚韧'),C('tough.s3','严厉/能吃苦','The coach is tough but fair, insisting that every player arrive on time.','教练要求严格但公正，坚持每位队员准时到场。','a tough coach; tough on someone','形容词，指要求严格、粗犷或能承受艰苦的。','the coach sets firm expectations.','严厉/能吃苦'),C('tough.s4','难嚼','The steak was so tough that the diners asked the chef to cook it longer.','牛排太难嚼了，食客请厨师再多煎一会儿。','tough meat; tough to chew','形容词，指食物难以切开或咀嚼的。','the meat is difficult to chew.','难嚼')],M('The plastic case was tough, so it shattered into pieces after one light tap.','The plastic case was tough, so it resisted damage when dropped.','tough材料坚韧耐用，不应轻轻一碰就碎。','meaning'),[Q(1,'A tough decision is…','difficult to make','easy and obvious','a very warm decision','Sense 1 is difficulty.','meaning'),Q(2,'Tough plastic is…','strong and resistant to damage','easy to tear','always flexible like cloth','Sense 2 describes durability.','context'),Q(3,'A tough but fair coach is…','strict while treating players fairly','unfair and careless','a person who writes a textbook','Sense 3 describes the coach’s manner.','meaning'),Q(4,'Tough steak is…','difficult to cut or chew','soft and tender','a course topic','Sense 4 is the food texture.','context')]);
P('toughen','Toughen combines tough with the verb-forming -en; it means make a person, material, or plant more resilient, or become more resilient.',[C('toughen.s1','使变坚韧','The training will toughen the young players before the demanding tournament.','训练会让年轻队员在艰苦的比赛前变得更加坚韧。','toughen someone/material; toughen up','动词，指使某人或某物更能承受困难或损坏。','the training builds physical and mental resilience.','使变坚韧'),C('toughen.s2','变坚强','She toughened after years of working outdoors in difficult conditions.','在艰苦环境中户外工作多年后，她变得更加坚强。','skin/material toughens; toughen over time','动词，指逐渐变得更坚韧、更坚固或不易受影响。','experience makes her more resilient.','变坚强')],M('The training toughened the players by making them weaker and less able to handle pressure.','The training toughened the players by building their strength and ability to handle pressure.','toughen表示增强承受力，不是削弱承受力。','meaning'),[Q(1,'Training toughens players means it…','makes them more resilient','makes them easier to injure','ends the tournament','Sense 1 is the causative verb.','meaning'),Q(2,'She toughened after years outdoors means she…','became stronger and more resilient','became less able to cope','changed into a topcoat','Sense 2 is the intransitive change.','context'),Q(1,'Which sentence uses toughen correctly?','The coach toughened the team with demanding practice.','The coach toughened by the team the practice.','The team toughening the coach yesterday.','The coach is the agent and team is the object.','grammar'),Q(1,'The suffix -en forms…','a verb meaning make or become tough','a noun for a whole amount','an adverb of direction','Toughen is the verb built from tough.','word-formation')]);
P('tour','Tour came through French from Latin tornus and Greek tornos, “a lathe or tool for drawing circles,” from a turning sense; it names a journey, a series of visits, or the act of travelling around.',[C('tour.s1','旅行','We went on a walking tour of the old city and visited its historic squares.','我们参加了老城徒步游，参观了几座历史广场。','go/take a tour; a guided tour of a city','名词，指为了游览而访问多个地点的一次旅行。','the visitors explore a series of places.','旅行'),C('tour.s2','巡演','The band is on tour and will play in five cities this month.','乐队正在巡演，本月将在五座城市演出。','go/be on tour; a concert tour','名词，指表演者、运动队或官员在多地进行的一系列访问。','the band performs in several locations.','巡演'),C('tour.s3','游览','They toured the old town on foot before taking the train home.','他们步行游览老城区后乘火车回家。','tour a city/museum; tour around','动词，指在一处地方四处参观，或到多个地方演出。','they visit several sites on foot.','游览')],M('They toured the old town by staying in one hotel room and visiting no place in the town.','They toured the old town on foot, visiting its squares and historic streets.','tour作动词表示四处参观，原句却说没有参观任何地方。','meaning'),[Q(1,'A city tour is…','a journey visiting several places','a protective layer of paint','a political system','Sense 1 is sightseeing.','meaning'),Q(2,'A band on tour…','performs in a series of places','stays at one venue forever','maps land contours','Sense 2 is a performance series.','context'),Q(3,'They toured the old town means they…','travelled around it to visit places','built a tower over it','bought and sold it','Sense 3 is the verb.','meaning'),Q(1,'The older root related to tour referred to…','turning or a tool for drawing circles','a name for a child’s toy','a legal witness','The journey sense developed through the idea of going around.','word-formation')]);
P('touring','Touring is formed from tour plus -ing; it describes travelling around places for visits or moving from place to place to give performances.',[C('touring.s1','旅行游览','We spent two weeks touring the west coast by train and ferry.','我们花了两周乘火车和渡轮游览西海岸。','touring the coast; touring holiday','形容词/动名词，指旅行中访问多处景点。','the travellers move around to see places.','旅行游览'),C('touring.s2','巡演','The orchestra returns to Europe for a touring season of concerts.','乐团将回到欧洲进行一季巡回音乐会演出。','touring company/band; touring season','形容词，指表演者在多地巡回演出或参赛的。','the orchestra gives performances in multiple cities.','巡演')],M('The orchestra had a touring season in one hall and gave no performances anywhere else.','The orchestra had a touring season and performed in concert halls across Europe.','touring season意味着到多地巡演，不只在一个场馆演出。','meaning'),[Q(1,'Touring the west coast means…','travelling around it and visiting places','staying in one room without moving','creating a map of the ocean floor','Sense 1 concerns sightseeing.','meaning'),Q(2,'A touring orchestra…','travels between places to perform','works only in a recording studio','runs a city government','Sense 2 is performance travel.','context'),Q(1,'Which phrase is natural?','a touring season of concerts','a season touringly of concert','touring concerts seasonly','Touring modifies season and signals a series of performances in places.','grammar'),Q(1,'Touring is formed from…','tour plus -ing','tour plus -less','towel plus -ing','The ending creates a participial/adjectival form of tour.','word-formation')]);
P('tourism','Tourism is formed from tourist/tour plus -ism; it names both the business serving visitors and the activity of visiting places for pleasure.',[C('tourism.s1','产业','Tourism provides most of the island’s income through hotels, guides, and ferry services.','旅游业通过酒店、导游和渡轮服务为岛上带来大部分收入。','tourism industry; promote/sustain tourism','名词，指为游客提供住宿、交通和服务的行业。','local businesses earn money from visitors.','产业'),C('tourism.s2','旅游活动','Mass tourism has changed the old town and crowded its narrow streets.','大众旅游改变了老城区，也挤满了狭窄街道。','mass/cultural tourism; tourism to a region','名词，指为娱乐而游览名胜或有趣地点的活动。','many people visit the area for pleasure.','旅游活动')],M('Tourism supports the island economy, but the sentence says no visitors use any hotel, guide, or transport service.','Tourism supports the island economy through visitor spending on hotels, guides, and transport.','旅游业的产业义依赖服务游客；无人使用服务就无法支撑所述收入。','meaning'),[Q(1,'Tourism as an industry provides…','services for people visiting a place','a medical tourniquet only','a noun for total control','Sense 1 is the business sector.','meaning'),Q(2,'Mass tourism means…','many people visiting places for pleasure','one person commuting to work','a small amount of rain','Sense 2 is the travel activity.','context'),Q(1,'Which phrase is natural?','tourism earns the region income','tourism earnly the region','income tourism to earns','Tourism is a singular activity noun and takes earns.','grammar'),Q(1,'The suffix -ism here turns tour/tourist into…','a field or activity','a person who performs an action','an adverb of manner','Tourism names the travel activity and its industry.','word-formation')]);
P('tourist','Tourist is formed from tour plus -ist, naming a person who travels for pleasure; as an adjective it describes places, services, or activities intended for visitors.',[C('tourist.s1','游客','Millions of tourists visit the museum each year to see the ancient collection.','每年有数百万游客来博物馆参观古代藏品。','tourist attraction/season; foreign tourists','名词，指为了游览而到某地旅行的人。','the visitors travel for enjoyment.','游客'),C('tourist.s2','游客化','The old harbour has become a tourist trap filled with souvenir stalls.','旧港口已经变成了游客陷阱，到处都是纪念品摊位。','tourist trap/area; tourist accommodation','形容词，指专为吸引游客或服务游客而设的。','the area targets visiting travellers.','游客化'),C('tourist.s3','旅游的','The tourist industry employs guides, hotel workers, and ferry crews.','旅游业雇用导游、酒店员工和渡轮船员。','tourist industry/season; tourist information','形容词，指与游览旅行有关的。','the adjective relates to travel for pleasure.','旅游的')],M('The tourists visited the museum as local employees working there every day, not as visitors.','The tourists visited the museum while travelling there for pleasure.','tourist名词指游览者，不是当地固定工作人员。','meaning'),[Q(1,'A tourist is someone who…','travels to enjoy a place','maps a region’s surface','is charged with a crime','That is the noun meaning.','meaning'),Q(2,'A tourist trap is…','an area or business targeting visitors','a harmless map symbol','a crop field cut into terraces','Sense 2 uses the adjective in a compound.','context'),Q(3,'The tourist industry is…','business connected with travel for pleasure','a group of political doctrines','an academic appointment system','Sense 3 is the adjective modifying industry.','meaning'),Q(1,'Tourist is formed from…','tour plus the person-forming suffix -ist','torture plus -ous','toward plus -s','The suffix identifies a person associated with touring.','word-formation')]);
P('tournament','Tournament came through Old French tornoiement, from tornoier, “to turn”; it first referred to a medieval contest of knights and now means a competition with rounds of matches.',[C('tournament.s1','比赛','She reached the final of the tennis tournament after winning four matches.','她赢下四场比赛后进入网球锦标赛决赛。','tennis/chess tournament; win/enter a tournament','名词，指多名选手或队伍通过一系列比赛争夺胜利的赛事。','several rounds lead to a final.','比赛'),C('tournament.s2','骑士比武','The museum’s painting shows knights meeting at a tournament in the Middle Ages.','博物馆的画作描绘了中世纪骑士在比武大会上交锋。','medieval tournament; jousting tournament','名词，历史上指中世纪骑士举行的比武竞赛。','the riders compete in a historical contest.','骑士比武')],M('She reached the final of the tournament without playing any match or defeating an opponent.','She reached the final of the tournament by winning the earlier rounds.','锦标赛由多轮比赛组成，进入决赛前需参加赛事。','meaning'),[Q(1,'A tennis tournament is…','a competition with a series of matches','a type of soil','a permanent job appointment','Sense 1 is the modern competition.','meaning'),Q(2,'A medieval tournament involved…','contests between knights','a group of place names','a river storm','Sense 2 is the historical use.','context'),Q(1,'Which phrase is natural?','reach the final of a tournament','reach a tournament finalingly','final tournament to reach of','Final commonly names the last round in an event.','collocation'),Q(1,'The Old French source referred to…','a tournament or contest','a handful of cloth','a total amount','The English word was transmitted from a medieval contest term.','word-formation')]);
P('tourniquet','Tourniquet comes from French tourniquet, from tourner, “to turn”; it is a band tightened around an arm or leg to compress blood vessels in an emergency.',C('tourniquet.s1','急救','The medic applied a tourniquet above the wound to control severe bleeding.','医护人员在伤口上方绑上止血带，以控制严重出血。','apply/tighten a tourniquet; emergency tourniquet','名词，指紧绕肢体并压迫血管以应急止血的装置。','the band compresses blood vessels above the wound.','急救'),M('The medic applied a tourniquet loosely below the wound so that blood flowed faster from it.','The medic applied a tourniquet tightly above the wound to slow severe bleeding.','止血带需在伤口上方压迫血管以减少出血，不是让出血加快。','meaning'),[Q(1,'A tourniquet is used to…','compress blood vessels to control severe bleeding','measure an engine’s turning force','dry hands after washing','That is the emergency-medical definition.','meaning'),Q(1,'Where did the medic place it?','Above the wound','On the opposite arm below the elbow','Around the neck','The context specifies placement above the wound.','context'),Q(1,'Which verb naturally collocates with tourniquet?','apply','sprinkle','testify','Apply a tourniquet is the standard phrase.','collocation'),Q(1,'French tourner, behind tourniquet, meant…','to turn','to be afraid','to weave','The device’s name comes from a verb meaning turn.','word-formation')]);
P('tout','Tout is a verb of uncertain origin; it means solicit or sell eagerly in public, praise something to attract buyers, or a person who resells tickets at inflated prices.',[C('tout.s1','兜售','Men were touting tickets outside the stadium before the match.','比赛开始前，有人在体育场外兜售门票。','tout for tickets; tout goods to visitors','动词，指在公共场所热切招揽顾客或兜售商品。','the sellers approach people to make a sale.','兜售'),C('tout.s2','吹捧','The resort is touted as a paradise for divers, though it has only one small reef.','这家度假村被吹捧为潜水者的天堂，尽管那里只有一小片珊瑚礁。','tout something as; be touted as','动词，指为了吸引支持或买家而大力称赞某物。','the description promotes the resort.','吹捧'),C('tout.s3','黄牛','Police arrested several touts who resold tickets near the gate at triple the price.','警方逮捕了几名在门口附近以三倍价格倒卖门票的黄牛。','ticket tout; touts outside a venue','名词，指买票后以更高价格转卖的人。','the sellers resell tickets for profit.','黄牛')],M('The resort was touted as a diving paradise, but the advertisement carefully avoided praising it or attracting visitors.','The resort was touted as a diving paradise to attract visitors.','tout something as指大力宣传或吹捧，目的往往是吸引顾客。','meaning'),[Q(1,'People touting tickets are…','eagerly trying to sell them','using them to dry their hands','studying place-name origins','Sense 1 is the verb for soliciting sales.','meaning'),Q(2,'A resort touted as a paradise is…','being praised to attract customers','being condemned in court','being pulled behind a truck','Sense 2 is promotional praise.','context'),Q(3,'Ticket touts are people who…','resell tickets at higher prices','write the original play','map the airport terminal','Sense 3 is the noun.','meaning'),Q(1,'The deeper origin of tout is…','uncertain','definitely Greek for place','definitely Latin for whole','The available etymology does not establish a certain root.','word-formation')]);
P('tow','Tow comes from Old English togian, “pull,” related to Old Norse toga; as a verb it pulls a vehicle behind another, and as a noun it names the act of pulling it.',[C('tow.s1','拖曳','The truck towed the broken bus to a repair shop on the edge of town.','卡车把抛锚的公交车拖到城边的修理厂。','tow a car/boat; be towed away','动词，指用另一辆车或船拖着故障车辆移动。','the truck pulls the disabled bus behind it.','拖曳'),C('tow.s2','拖车','The car was on tow after its engine failed on the highway.','汽车在高速公路上发动机故障后被拖走。','in/on tow; take a vehicle in tow','名词，指拖车或拖曳车辆的行为。','the broken car is being pulled by another vehicle.','拖车')],M('The truck towed the broken bus by leaving it behind and driving away without pulling it.','The truck towed the broken bus by pulling it to the repair shop.','tow表示拖着移动，不能是不牵引就独自离开。','meaning'),[Q(1,'The truck towed the bus means it…','pulled it behind to another place','sold it at a market','painted its upper layer','Sense 1 is the verb.','meaning'),Q(2,'A car on tow is…','being pulled by another vehicle','inside a theatre','a kind of tourist','Sense 2 is the noun phrase for towing.','context'),Q(1,'Which phrase is natural?','tow a broken car','tow a car into towingly','a tow to broken of car','Tow takes the vehicle as its object.','grammar'),Q(1,'Old English togian meant…','to pull','to name a region','to give thanks','The verb preserves the pulling sense.','word-formation')]);
P('toward','Toward comes from Old English tóweard, built from to plus an element meaning “in the direction of”; it marks direction, attitude, time shortly before, or contribution to a purpose.',[C('toward.s1','方向','She walked toward the door when the meeting ended.','会议结束后，她朝门口走去。','walk/move toward; head toward a place','介词，指朝某人、地点或方向移动。','her movement is directed to the door.','方向'),C('toward.s2','态度','His attitude toward careful research is serious and respectful.','他对严谨研究的态度认真而尊重。','attitude/feelings toward someone; kind toward','介词，指对某人或某事所持的态度。','the phrase describes how he regards research.','态度'),C('toward.s3','接近时间','It grew cold toward evening as the sun disappeared behind the hills.','太阳隐到山后时，傍晚前后天气变冷了。','toward evening; toward the end of the year','介词，指接近某个时间点。','the cold arrives as evening approaches.','接近时间'),C('toward.s4','用于/贡献','The gift goes toward the school fund for new library books.','这笔捐款用于学校基金，购买新的图书馆藏书。','go toward a cost/goal; contribute toward','介词，指作为某项费用或目标的一部分。','the gift contributes to the fund.','用于/贡献')],M('She walked toward the door, moving away from it in the opposite direction.','She walked toward the door, moving in its direction.','toward表示朝向某处，与反方向离开相反。','meaning'),[Q(1,'Walked toward the door means…','moved in the door’s direction','moved away from it','arrived at a theatre','Sense 1 is direction.','meaning'),Q(2,'His attitude toward research describes…','how he feels about it','where he walks','how much a book costs','Sense 2 is an attitude.','context'),Q(3,'Toward evening means…','as evening approaches','at noon exactly','the day after tomorrow','Sense 3 marks approximate time.','meaning'),Q(4,'A gift going toward a school fund…','contributes to that purpose','moves away from the goal','is a type of tourist service','Sense 4 describes contribution.','context')]);
P('towards','Towards is the variant spelling of toward, with the same uses for direction, attitude, and contribution; both spellings are standard, with regional preferences.',[C('towards.s1','方向','She walked towards the station after leaving the museum.','她离开博物馆后朝车站走去。','move/walk towards; turn towards a place','介词，指朝某人、地点或方位移动。','the station is the direction of movement.','方向'),C('towards.s2','态度/用途','He put the cash towards a new bike and remained friendly towards the seller.','他把现金用于买新自行车，对卖家仍很友好。','attitude towards; put money towards a goal','介词，指对某人持有的态度，或作为某用途的贡献。','the sentence shows both relational and contribution uses.','态度/用途')],M('She walked towards the station but continued moving farther away from it.','She walked towards the station, moving in its direction.','towards与toward同义，都表示朝某处前进。','meaning'),[Q(1,'Walked towards the station means…','moved in its direction','moved away from it','waited at a tourniquet','That is the directional use.','meaning'),Q(2,'Friendly towards the seller describes…','his attitude to the seller','the route’s end point','the amount of rainfall','Sense 2 is relational attitude.','context'),Q(1,'Toward and towards are…','standard spelling variants with the same core meanings','different words with opposite directions','one noun and one verb','The final s is a regional spelling preference, not a meaning change.','spelling'),Q(1,'Which phrase is natural?','put money towards a bike','put towardsly money a bike','money bike towards putly','Towards introduces the goal receiving a contribution.','grammar')]);
P('towel','Towel came through Old French toaille for a piece of cloth used for drying; its deeper origin is uncertain. It can be cloth or paper for drying hands, skin, dishes, or spills.',[C('towel.s1','擦干身体','Dry your hands on the clean towel beside the sink.','用水槽旁边的干净毛巾擦干双手。','bath/hand towel; dry yourself with a towel','名词，指用于擦干皮肤、头发或手的布或纸。','the cloth absorbs water from hands.','擦干身体'),C('towel.s2','擦拭物品','There is a paper towel by the sink for wiping up spills.','水槽旁有厨房纸巾，可以擦掉洒出的液体。','paper/kitchen towel; dry dishes with a towel','名词，指用于擦干餐具或擦拭泼洒物的布或纸。','the paper absorbs the spilled liquid.','擦拭物品')],M('She dried her hands on a towel by rubbing them with a dry metal fork.','She dried her hands on a towel by rubbing them with the absorbent cloth.','towel是吸水的布或纸，金属叉子不是合适的擦手毛巾。','meaning'),[Q(1,'A hand towel is used to…','dry skin or hands','measure political torque','carry a burning flame','Sense 1 is personal drying.','meaning'),Q(2,'A paper towel by the sink is for…','wiping up spills','writing a testament','mapping a townscape','Sense 2 is cleaning or drying objects.','context'),Q(1,'Which phrase is natural?','dry your hands on a towel','dry your hands by a towel of','towel your dry hands only','On introduces the surface used to dry hands.','grammar'),Q(1,'The deeper history of towel is…','uncertain beyond its route through Old French','definitely from Greek “place”','definitely from Latin “third”','The earlier source is not established with confidence.','word-formation')]);
P('tower','Tower comes through Old French tor from Latin turris, “tower,” ultimately Greek turris; it names a tall narrow structure, control equipment, or the act of rising much higher than nearby things.',[C('tower.s1','建筑','The church tower is visible for miles across the flat countryside.','在平坦乡间，几英里外都能看到教堂塔楼。','church/watch/water tower; climb a tower','名词，指高而窄的建筑物或建筑的一部分。','the structure rises above surrounding land.','建筑'),C('tower.s2','控制设备','Planes waited while the airport control tower checked the runway.','机场控制塔检查跑道时，飞机在等待。','control tower; tower operator','名词，指塔式控制设备或其所在的高塔。','the staff coordinate aircraft from the tower.','控制设备'),C('tower.s3','高出','The old lighthouse towers over the low houses beside the harbour.','旧灯塔高耸在港口旁低矮房屋之上。','tower over someone/something; tower above','动词，指比周围的人或物高出很多。','the lighthouse is much taller than nearby homes.','高出')],M('The church tower was visible for miles because it stood below every nearby hill and building.','The church tower was visible for miles because it rose above the surrounding countryside.','tower作为建筑物通常高耸，原句却说它低于附近所有地物。','meaning'),[Q(1,'A church tower is…','a tall narrow part of a building','a flat cloth used for drying','a slow-moving animal','Sense 1 is the building.','meaning'),Q(2,'An airport control tower is used to…','coordinate aircraft and runway activity','dry passengers’ hands','hold a tournament','Sense 2 is the control facility.','context'),Q(3,'The lighthouse towers over houses means it…','is much taller than them','is shorter than every house','is being towed behind them','Sense 3 is the verb.','meaning'),Q(1,'Latin turris meant…','tower','turning force','a public holiday','The English word was borrowed through French from a Latin word for tower.','word-formation')]);
P('tower over','Tower over combines tower with over; it means be much taller than nearby things or be much greater in size, power, or importance.',[C('tower over.s1','高耸','The castle towers over the small town from its rocky hilltop.','城堡从岩石山顶高耸在小镇上方。','tower over a town; tower above the rooftops','短语动词，指在高度上远高于周围事物。','the castle stands far above the low buildings.','高耸'),C('tower over.s2','显著高于','One firm towers over every rival in the region because it serves most customers.','由于服务了大多数顾客，一家公司在该地区远远领先于所有对手。','tower over rivals; tower over competitors in size','短语动词，比喻在规模、力量或重要性上远胜于他者。','the company is much larger and more influential.','显著高于')],M('The castle towered over the town because it was much lower than every nearby roof.','The castle towered over the town because it stood high above the nearby roofs.','tower over表示明显高于周围事物，不是低于它们。','meaning'),[Q(1,'The castle towers over the town means it…','stands much higher than nearby buildings','lies under every building','is a type of textile','Sense 1 is physical height.','meaning'),Q(2,'A firm towers over rivals means it…','is much greater in size or influence','has exactly the same market share as every rival','has gone out of business','Sense 2 is figurative superiority.','context'),Q(1,'Which phrase is natural?','tower over the rooftops','tower on the rooftops overly','over the tower rooftops','Over introduces what is lower or surpassed.','grammar'),Q(1,'Tower over is a…','verb plus preposition/particle expressing superiority','noun for an instrument that turns','compound naming a small towel','The phrase extends physical height to figurative dominance.','word-formation')]);
P('towering','Towering is the -ing form of tower used adjectivally; it means extremely tall or much greater than others in ability, size, or importance.',[C('towering.s1','高耸','Towering cliffs rose on either side of the bay as the boat entered.','船驶入海湾时，两侧高耸的峭壁拔地而起。','towering cliffs/mountains; towering above','形容词，指高得仿佛直入天空的。','the cliffs rise far above the water.','高耸'),C('towering.s2','杰出','She became a towering figure in modern engineering after designing the bridge.','设计这座桥后，她成为现代工程领域的杰出人物。','towering figure/achievement; towering influence','形容词，比喻在能力、规模或重要性上远超他者的。','her work has exceptional influence.','杰出')],M('Towering cliffs surrounded the bay, but they were lower than the water and impossible to see.','Towering cliffs rose high above the water on both sides of the bay.','towering表示异常高耸，与低于水面相反。','meaning'),[Q(1,'Towering cliffs are…','extremely tall cliffs','very short rocks','a collection of names','Sense 1 is literal height.','meaning'),Q(2,'A towering figure in engineering is…','a person of exceptional importance','a person physically short and unknown','a kind of animal','Sense 2 is figurative prominence.','context'),Q(1,'Which phrase is natural?','a towering achievement','an achievement toweringly','towering of achievemently','Towering is an adjective modifying achievement.','grammar'),Q(1,'Towering is formed from…','tower plus -ing','town plus -scape','tour plus -ism','The participial form is used as an adjective.','word-formation')]);
P('town','Town comes from Old English tun, “enclosure, farmstead,” from a Germanic word for a fenced place; it names an urban settlement or its central shopping area and inhabitants.',[C('town.s1','城镇','She grew up in a small town with one high street and a weekly market.','她在一个只有一条主街和每周集市的小镇长大。','small/market town; live in a town','名词，指规模大于村庄、有住宅、商店和街道的聚居地。','the place has streets, homes, and shops.','城镇'),C('town.s2','市中心/镇民','I am going into town this afternoon to buy groceries.','我今天下午要进城买些食品杂货。','go into town; town centre; the whole town','名词，可指城镇的中心商业区，也可指当地居民。','the speaker means the shopping area.','市中心/镇民')],M('She grew up in a small town, a place with no houses, shops, streets, or residents.','She grew up in a small town with homes, shops, streets, and local residents.','town是有人居住并有街道商铺的聚居地，不是无人区域。','meaning'),[Q(1,'A small town is…','a settlement with homes, streets, and shops','a single isolated hill','a venue for a play only','Sense 1 is the settlement.','meaning'),Q(2,'Going into town usually means going to…','the central shopping area','a remote farm with no shops','the next day','Sense 2 is the town centre use.','context'),Q(1,'Which phrase is natural?','live in a town','live on townly','town in live at','In introduces the settlement where someone lives.','grammar'),Q(1,'Old English tun originally referred to…','an enclosure or farmstead','a political doctrine','a twisting motion','The word developed from a term for a fenced or settled place.','word-formation')]);
P('townscape','Townscape combines town with -scape, by analogy with landscape; it names the general view of a town’s buildings and streets or an artwork showing that view.',C('townscape.s1','城市景观','The artist painted the old townscape with chimneys, narrow streets, and tiled roofs.','画家描绘了老城景观，包括烟囱、窄街和瓦顶。','historic/urban townscape; preserve the townscape','名词，指城镇建筑与街道构成的整体景观，也可指描绘它的作品。','the view combines multiple urban features.','城市景观'),M('The townscape showed only an empty ocean with no town buildings or streets.','The townscape showed the town’s rooftops, chimneys, and streets together.','townscape描绘的是城镇整体景观，不是没有城镇的海洋。','meaning'),[Q(1,'A townscape is…','the general view of a town’s buildings and streets','a system of place-name origins','the turning force of a shaft','That is the landscape-related meaning.','meaning'),Q(1,'What features appeared in the painting?','Chimneys, narrow streets, and tiled roofs','Only open sea and no town','A medical tourniquet','The example lists parts of the old urban view.','context'),Q(1,'Which phrase is natural?','preserve the historic townscape','townscape preservely historic','historic of townscape preserve','Preserve takes townscape as its object.','collocation'),Q(1,'The suffix -scape is associated with…','a view or scene, as in landscape','a person who trades','a noun for fear','Townscape is modelled on landscape for an urban scene.','word-formation')]);
P('townspeople','Townspeople combines town and people; it means the inhabitants of a town taken together as a group.',C('townspeople.s1','居民','The townspeople gathered in the square to welcome the new library staff.','镇民们聚集在广场上，欢迎新来的图书馆工作人员。','local townspeople; townspeople gathered','名词复数，指一座城镇的居民整体。','the group consists of people who live in town.','居民'),M('The townspeople gathered in the square, although not one person in the group lived in the town.','The townspeople gathered in the square as residents of the town.','townspeople指城镇居民，不能指其中无人住在当地的人。','meaning'),[Q(1,'Townspeople are…','the inhabitants of a town','the visitors who never stay','a group of court witnesses','That is the compound’s meaning.','meaning'),Q(1,'Where did they gather?','In the town square','At a remote lighthouse','Inside a school textbook','The context identifies the central square.','context'),Q(1,'Which verb agrees with townspeople?','The townspeople gathered.','The townspeople gathers.','The townspeople gathering yesterday.','Townspeople is plural and takes gathered.','grammar'),Q(1,'Townspeople combines…','town and people','tour and tourist','tough and -en','The compound names people who live in a town.','word-formation')]);
P('toxic','Toxic comes from Greek toxikon, “poison for arrows,” related to toxon, “bow”; it describes poisonous substances and, figuratively, harmful social conditions.',[C('toxic.s1','有毒','The fumes are toxic, so workers must leave the room and wear protective equipment.','这些烟雾有毒，因此工人必须离开房间并穿戴防护装备。','toxic gas/fumes; toxic substance','形容词，指含有毒物或由毒物引起的。','exposure could poison or injure workers.','有毒'),C('toxic.s2','有害氛围','The office atmosphere became toxic after managers encouraged staff to blame one another.','管理者鼓励员工互相指责后，办公室氛围变得有害。','toxic relationship/workplace; toxic atmosphere','形容词，比喻令人极不愉快、可能造成伤害的。','the hostile environment harms staff.','有害氛围')],M('The toxic fumes were safe to breathe and caused no risk to anyone in the room.','The toxic fumes were dangerous to breathe, so workers evacuated the room.','toxic描述有毒有害，不能称为毫无风险。','meaning'),[Q(1,'Toxic fumes are…','poisonous or harmful to breathe','pleasantly scented and harmless','a type of road vehicle','Sense 1 is literal poison.','meaning'),Q(2,'A toxic workplace is…','an unpleasant environment likely to harm people','a completely supportive and healthy office','a steep landscape','Sense 2 is figurative harm.','context'),Q(1,'Which phrase is natural?','toxic chemicals','chemicals toxicly','toxicity chemicals are','Toxic is an adjective modifying chemicals.','grammar'),Q(1,'Greek toxikon referred to…','poison used on arrows','a town enclosure','a day after an event','The ancient root was associated with poison for arrows.','word-formation')]);
P('toxin','Toxin comes from Greek toxikon, “poison for arrows,” plus the scientific noun ending -in; it means a poisonous substance produced by a living organism.',C('toxin.s1','生物毒素','Some bacteria release a toxin that causes illness if it enters the bloodstream.','有些细菌会释放毒素，进入血液后可能引发疾病。','bacterial/plant toxin; release/neutralize a toxin','名词，指由细菌、植物或动物等生物产生的有毒物质。','the substance is produced by bacteria and harms the body.','生物毒素'),M('The bacteria released a toxin, a harmless nutrient produced by no living organism.','The bacteria released a toxin, a poisonous substance produced by a living organism.','toxin指生物产生的有毒物质，不是无害营养物。','meaning'),[Q(1,'A toxin is…','a poisonous substance made by a living thing','a type of city view','a fabric for drying hands','That is the biological definition.','meaning'),Q(1,'What can the toxin in the example cause?','Illness if it enters the bloodstream','A tour around the city','A solar eclipse','The context states its potential health effect.','context'),Q(1,'Which phrase is natural?','a bacterial toxin','bacteria toxin ofly','toxin bacterialness','Bacterial is an adjective modifying toxin.','grammar'),Q(1,'The ancient Greek source referred to…','poison for arrows','a place name','the end of a school term','The modern biological word descends from a poison term.','word-formation')]);
P('toy','Toy is a word of uncertain origin, recorded in Middle English for a trifle or playful thing; it now names an object for children and also means handle idly or consider casually.',[C('toy.s1','玩具','The baby dropped the toy, and her father picked it up from the carpet.','宝宝把玩具掉在地上，父亲从地毯上捡了起来。','children’s toy; toy train/doll','名词，指供儿童玩耍的物品。','the object is used for play.','玩具'),C('toy.s2','摆弄','He toyed with his spoon during the long meeting instead of taking notes.','漫长会议中，他一直摆弄勺子，没有做笔记。','toy with an object; toy with a pen','动词，指漫不经心地触碰或摆弄某物。','the hand moves the spoon without a serious purpose.','摆弄'),C('toy.s3','考虑','She toyed with the idea of moving abroad but made no decision.','她曾考虑过移居国外，但没有作出决定。','toy with an idea/plan; toy with the possibility','动词，指随意考虑一个想法但尚未决定实施。','the possibility is considered casually rather than chosen.','考虑')],M('She toyed with the idea of moving abroad by making a final decision and buying a one-way ticket.','She toyed with the idea of moving abroad but had not decided to do it.','toy with an idea表示随意考虑但尚未决定，已经作出最终决定则不符。','meaning'),[Q(1,'A child’s toy is…','an object intended for play','a poisonous substance','a town’s inhabitants','Sense 1 is the noun.','meaning'),Q(2,'He toyed with his spoon means he…','handled it idly','used it to eat a full meal','sold it to a tourist','Sense 2 is casual physical handling.','context'),Q(3,'She toyed with the idea means she…','considered it casually without deciding','made a final commitment','rejected the idea without thought','Sense 3 is tentative consideration.','meaning'),Q(1,'The early meaning of toy included…','a trifle or playful thing','a political system','a very hot climate','The modern plaything sense developed from the older playful/trivial use.','word-formation')]);
P('toy with','Toy with uses the verb toy, whose origin is uncertain, plus with; it means handle an object idly or consider an idea casually without deciding to act.',[C('toy with.s1','摆弄','He toyed with the pen during the meeting while listening to the long report.','漫长报告期间，他一边听一边摆弄手中的笔。','toy with a pen/object; toy with something in one’s hands','短语动词，指漫不经心地玩弄或摆弄某物。','the pen is moved idly rather than used to write.','摆弄'),C('toy with.s2','考虑','They toyed with the idea of moving abroad but never chose a country.','他们考虑过移居国外，但从未选定目的地。','toy with the idea/possibility; toy with a plan','短语动词，指随意考虑一个想法但还没有决定实施。','they consider the possibility without committing.','考虑')],M('They toyed with the idea of moving abroad by signing a final lease and booking a one-way move.','They toyed with the idea of moving abroad but made no firm decision.','toy with an idea表示尚未下定决心地考虑，与已经落实的安排不同。','meaning'),[Q(1,'He toyed with a pen means he…','handled it idly while listening','used it to sign the final contract','threw it across the room','Sense 1 is casual handling.','context'),Q(2,'They toyed with moving abroad means they…','considered it casually without deciding','had already moved and settled','refused to consider it at all','Sense 2 is tentative consideration.','meaning'),Q(1,'Which phrase is natural?','toy with the possibility','toy the possibility withly','with toy possibility of','With follows toy in this phrasal verb.','grammar'),Q(1,'Toy with is built from…','toy, a verb meaning play or trifle, plus with','tough plus -en','track plus pad','The phrase extends casual play to casual consideration.','word-formation')]);
P('trace','Trace came through Old French tracier from Latin tractus, “a drawing out,” from trahere, “draw”; it names a mark or small amount, and means follow origins or copy outlines.',[C('trace.s1','痕迹','Police found no trace of the missing letter in the desk or filing cabinet.','警方在书桌和文件柜里都没有发现那封失踪信件的踪迹。','leave/find no trace; trace of evidence','名词，指表明某人或某物曾存在的一点标记或迹象。','the mark or evidence is absent.','痕迹'),C('trace.s2','少量','There was only a trace of smoke in the air after the candle went out.','蜡烛熄灭后，空气中只残留一丝烟味。','a trace of salt/smoke; trace amount','名词，指极少量的某物。','the smoke is present only in a tiny amount.','少量'),C('trace.s3','追查','Investigators traced the anonymous call to a phone registered at the office.','调查人员追查到匿名电话来自办公室登记的一部电话。','trace a call/source/origin; trace something back to','动词，指通过仔细查找确定人、事物或来源。','records allow investigators to identify where it came from.','追查'),C('trace.s4','描摹','The students traced the map onto thin paper to copy its borders.','学生们把地图描到薄纸上，复制其边界线。','trace a drawing/map; trace the outline','动词，指沿着图画线条描摹复制。','the pencil follows the map’s existing lines.','描摹')],M('There was a trace of smoke, meaning a thick cloud filled every room.','There was only a trace of smoke, a very small amount after the candle went out.','trace表示极少量，不是充满房间的浓烟。','meaning'),[Q(1,'No trace of the letter means…','no mark or evidence of it was found','many copies were found','it was used as a route','Sense 1 is evidence or a mark.','meaning'),Q(2,'A trace of smoke is…','a very small amount','a dense cloud filling the room','a legal statement','Sense 2 is a tiny quantity.','context'),Q(3,'Investigators traced the call means they…','found its source','copied its outline on paper','sold it at a higher price','Sense 3 is the verb for locating an origin.','meaning'),Q(4,'The students traced a map by…','following its lines to copy them','erasing every border','measuring its total weight','Sense 4 is copying an outline.','context')]);
P('track','Track came through Old French trac/track; the noun’s earliest history is uncertain, while the verb traces to tracier and Latin tractus, “a drawing out.” It means marks, a path or rail line, a recording, or following progress.',[C('track.s1','足迹','We followed the deer tracks in the snow until they reached the forest edge.','我们沿着雪地里的鹿足迹追踪，直到它们延伸到森林边缘。','animal/foot tracks; follow a track','名词，指人、动物或车辆留下的痕迹。','the marks reveal where the deer walked.','足迹'),C('track.s2','路线/跑道','The train left the track near the station, so the line was closed.','火车在车站附近脱轨，因此线路关闭。','railway/racing track; leave the track','名词，指狭窄道路、铁路轨道或比赛跑道。','the train is no longer on its rails.','路线/跑道'),C('track.s3','录音曲目','The third track on the album is my favourite song.','这张专辑的第三首曲目是我最喜欢的歌。','a track on an album; track listing','名词，指录音中的一首歌曲或一段音频。','the song is one numbered item on the album.','录音曲目'),C('track.s4','跟踪','Satellites track the storm as it moves across the ocean.','卫星跟踪风暴在海洋上移动的过程。','track a storm/person/progress; track down','动词，指持续追踪某人、动物或事物的行踪或进展。','satellites follow the storm’s location.','跟踪')],M('The train left the track but remained safely on the rails throughout the journey.','The train left the track and came off its rails near the station.','leave the track表示脱离轨道，不能同时说一直留在轨道上。','meaning'),[Q(1,'Deer tracks in snow are…','marks left by the animal','songs on an album','a device for moving a cursor','Sense 1 is the footprint meaning.','meaning'),Q(2,'A railway track is…','the rails a train runs on','a place-name study','a piece of clothing','Sense 2 concerns a route.','context'),Q(3,'The third track on an album is…','a recorded song or audio item','a hoofprint','a city’s central shopping area','Sense 3 is the recording meaning.','meaning'),Q(4,'Satellites track a storm by…','following its position and movement','copying its outline on paper','pulling it behind a truck','Sense 4 is the verb for following.','context')]);
P('trackpad','Trackpad combines track with pad; it names the flat touch-sensitive area on a laptop used to move and control the pointer on the screen.',C('trackpad.s1','电脑设备','The trackpad stopped responding, so she connected a mouse to finish the presentation.','触控板停止响应后，她接上鼠标完成了演示。','laptop trackpad; tap/swipe on a trackpad','名词，指通过手指滑动来控制屏幕光标的笔记本电脑平面触控区。','finger movement on the pad controls the pointer.','电脑设备'),M('She moved the cursor with the trackpad by pressing buttons on a floor mat across the room.','She moved the cursor by sliding a finger across the laptop trackpad.','trackpad是笔记本电脑上的触控区域，不是远处的地垫。','meaning'),[Q(1,'A laptop trackpad is used to…','control the on-screen pointer with a finger','print a page on paper','measure engine torque','That is the device’s function.','meaning'),Q(1,'Why did she connect a mouse?','The trackpad stopped responding','The computer had no screen','She was going on a city tour','The context directly states the reason.','context'),Q(1,'Which phrase is natural?','swipe on the trackpad','swipe the trackpad with a towel on','trackpad to swipe atly','On identifies the surface used for the gesture.','grammar'),Q(1,'Trackpad combines track with…','pad, a flat control surface','totem, a clan emblem','tragedy, a dramatic story','The compound names the surface used to track the pointer.','word-formation')]);
P('tract','Tract comes from Latin tractus, “a drawing out or extent,” from trahere, “draw”; it names a large area, a connected body system, or a short persuasive text.',[C('tract.s1','大片土地','Vast tracts of farmland were flooded after the river broke its banks.','河流决堤后，大片农田被淹。','tract of land; large/vast tract','名词，指一大片连续区域或土地。','the flooded area covers extensive farmland.','大片土地'),C('tract.s2','器官系统','The infection spread through the digestive tract and caused severe pain.','感染扩散到消化道，引起了剧烈疼痛。','digestive/respiratory tract; intestinal tract','名词，指身体中相互连接、共同发挥功能的一组器官。','connected organs carry food through the body.','器官系统'),C('tract.s3','宣传小册子','Volunteers handed out a short tract about protecting local wetlands.','志愿者分发了一本关于保护当地湿地的短篇宣传册。','religious/political tract; distribute a tract','名词，指常带有宗教或政治观点的短篇文章或小册子。','the printed text argues for a cause.','宣传小册子')],M('The digestive tract was a single isolated tooth with no connected organs.','The digestive tract was the connected system of organs involved in digestion.','digestive tract指相互连接的消化器官系统，不是单独一颗牙。','meaning'),[Q(1,'A vast tract of farmland is…','a large continuous area of land','a short religious pamphlet','a laptop control surface','Sense 1 is an area.','meaning'),Q(2,'The digestive tract is…','a connected system of organs','a single isolated muscle','a railway line','Sense 2 is the body-system use.','context'),Q(3,'A political tract is…','a short text promoting a political view','a thick towel','a severe storm','Sense 3 is the pamphlet meaning.','meaning'),Q(1,'Latin tractus was related to…','drawing out or an extent','giving thanks','turning hot','The root connects pulling/drawing with an extended area or text.','word-formation')]);
P('tractable','Tractable comes from Latin tractabilis, “manageable,” from tractare, “handle or deal with”; it describes something easy to control, teach, or work with.',[C('tractable.s1','易管教','The new puppy proved tractable and learned to sit after only a few lessons.','这只小狗很容易训练，只上了几节课就学会了坐下。','tractable child/animal; easy to train','形容词，指容易控制、训练或教导的。','the puppy responds readily to instruction.','易管教'),C('tractable.s2','易处理','The clay is tractable when damp and can be shaped into small bowls.','黏土潮湿时容易塑形，可以做成小碗。','tractable problem/material; tractable to analysis','形容词，指容易处理或塑造成所需形式的。','the material yields readily to shaping.','易处理')],M('The puppy was tractable, so it refused every command and could not be taught anything.','The puppy was tractable, so it learned the commands quickly.','tractable表示容易训练，不能用来形容完全不服从且无法教导。','meaning'),[Q(1,'A tractable puppy is…','easy to train and control','impossible to teach','made from a plant toxin','Sense 1 describes behaviour.','meaning'),Q(2,'Tractable clay is…','easy to shape','too hard to handle','a court statement','Sense 2 describes material that is workable.','context'),Q(1,'Which phrase is natural?','a tractable problem','a tractablely problem','problem tractability to easy','Tractable is an adjective modifying problem.','grammar'),Q(1,'Latin tractare meant…','to handle or deal with','to count as a whole','to make a performance','The source verb relates to handling something.','word-formation')]);
P('traction','Traction comes from Latin tractio, “a drawing or pulling,” from trahere, “draw”; it means grip between a wheel and a surface or growing support for an idea.',[C('traction.s1','抓地力','The new tires provide better traction on icy roads.','新轮胎在结冰路面上抓地力更强。','gain/lose traction; tire traction on ice','名词，指车轮与地面之间防止打滑的摩擦力。','the tires grip the road surface.','抓地力'),C('traction.s2','支持度','The campaign gained traction online after several local groups shared the proposal.','几个当地团体分享了提案后，活动在网上获得了更多支持。','gain/gather traction; gain traction with users','名词，比喻某想法或产品逐渐获得支持或进展。','more people begin to back the campaign.','支持度')],M('The tires had good traction on the ice, so the car slid freely with no grip at all.','The tires had poor traction on the ice, so the car slid without much grip.','traction指抓地力；若完全打滑应说抓地力不足。','meaning'),[Q(1,'Tire traction is…','the grip that helps a wheel avoid sliding','a type of car window','the final stop on a route','Sense 1 is the physical grip.','meaning'),Q(2,'A campaign gaining traction means it…','is gaining support or progress','is losing every supporter','is being pulled behind a truck','Sense 2 is figurative momentum.','context'),Q(1,'Which phrase is natural?','gain traction with users','traction gainly users','users with traction to gain','Gain traction is a standard expression.','collocation'),Q(1,'Latin tractio referred to…','drawing or pulling','a city’s view','an animal’s winter sleep','The word’s root carries the idea of pulling or grip.','word-formation')]);
P('tractor','Tractor comes from Latin trahere, “to pull,” with the agent ending -or; it names a powerful vehicle that pulls farm equipment or the front unit of an articulated lorry.',[C('tractor.s1','农用车','The tractor pulled a plough across the muddy field before sunrise.','天亮前，拖拉机在泥泞田地里拉着犁前行。','farm tractor; tractor pulls a plough','名词，指用于牵引犁和其他农具的强力农用车辆。','the vehicle pulls farming equipment.','农用车'),C('tractor.s2','卡车牵引车','The tractor unit was unhitched from the trailer at the depot.','牵引车在车场与拖车脱开。','tractor unit; lorry tractor','名词，指大型铰接式卡车前部负责牵引拖车的部分。','the front unit is separated from its trailer.','卡车牵引车')],M('The farm tractor pulled the plough by being a small passenger car with no towing power.','The farm tractor pulled the plough with its powerful engine.','tractor是用于牵引设备的强力车辆，不是没有牵引能力的小轿车。','meaning'),[Q(1,'A farm tractor is used to…','pull ploughs and other machines','dry dishes','print a textbook','Sense 1 is agricultural.','meaning'),Q(2,'A tractor unit is…','the front of a lorry that pulls a trailer','the trailer being pulled','an airport control room','Sense 2 is the vehicle part.','context'),Q(1,'Which phrase is natural?','a tractor pulled the plough','a plough tractored by pullingly','tractor the plough of pull','Tractor is the subject that pulls the plough.','grammar'),Q(1,'Latin trahere meant…','to pull or draw','to frighten','to name a place','The vehicle’s name refers to its pulling function.','word-formation')]);
P('trade','Trade has a debated history; an early English sense referred to a course or way of doing things, while later uses covered buying and selling and skilled occupations.',[C('trade.s1','买卖','Trade between the two countries grew after the new port opened.','新港口开放后，两国之间的贸易增长了。','international/free trade; trade in goods','名词，指买卖商品或服务的活动。','the countries exchange goods commercially.','买卖'),C('trade.s2','手艺','He learned his trade as a carpenter from his aunt, an experienced craftworker.','他跟随经验丰富的姨妈学习木匠手艺。','learn/practise a trade; skilled trade','名词，指需要实用技能、尤其是手工技能的职业。','carpentry is a skilled occupation.','手艺'),C('trade.s3','交易','They trade grain for machinery with a neighbouring farm cooperative.','他们与邻近农场合作社用粮食换农机。','trade goods for something; trade with a partner','动词，指买卖商品，或以物换物。','grain is exchanged for machinery.','交易')],M('The two countries traded goods, meaning neither side bought, sold, or exchanged anything.','The two countries traded goods through the new port.','trade表示买卖或交换，原句否认发生任何交易。','meaning'),[Q(1,'Trade between countries is…','the buying and selling of goods or services','a system of kinship rituals','a theatre performance','Sense 1 is commerce.','meaning'),Q(2,'A carpenter’s trade is…','a skilled occupation','a trackpad surface','a group of totems','Sense 2 is a profession requiring skills.','context'),Q(3,'They trade grain for machinery means they…','exchange grain to receive machinery','use the machinery to dry grain','refuse any exchange','Sense 3 is the verb.','meaning'),Q(1,'The history of trade is…','debated, with early senses of a course or way','certainly from Greek for theatre','certainly from Latin for whole','The deeper source is uncertain and should be presented cautiously.','word-formation')]);
P('trademark','Trademark combines trade with mark; it names a legally protected company name or symbol and, figuratively, a feature that identifies someone or something.',[C('trademark.s1','商标','The company registered its trademark before selling the new product abroad.','公司在向海外销售新产品前注册了商标。','registered trademark; trademark symbol/name','名词，指依法受保护、用于识别公司或产品的名称或标志。','registration protects the identifying sign.','商标'),C('trademark.s2','标志性特点','Dry humour became the comedian’s trademark over a long career.','长期演艺生涯中，冷面幽默成了这位喜剧演员的标志。','someone’s trademark style; a trademark feature','名词，比喻能识别某人或某物的典型特点。','the humour repeatedly identifies the performer.','标志性特点'),C('trademark.s3','注册商标','The firm trademarked the logo before launching its international campaign.','公司在发起国际宣传活动前为标志注册了商标。','trademark a name/logo; trademarked product','动词，指把名称或标志注册为受法律保护的商标。','the company legally registers its logo.','注册商标')],M('The firm trademarked its logo by giving up legal protection and inviting rivals to copy it freely.','The firm trademarked its logo by registering it for legal protection.','trademark作动词是注册商标以获得保护，与放弃保护相反。','meaning'),[Q(1,'A registered trademark is…','a legally protected name or symbol','a customer review only','a type of touring season','Sense 1 is the legal identifier.','meaning'),Q(2,'Dry humour as a comedian’s trademark is…','a distinctive identifying feature','a registered company name','a farming vehicle','Sense 2 is figurative.','context'),Q(3,'To trademark a logo is to…','register it for legal protection','erase it from every product','sell the logo to a tourist','Sense 3 is the verb.','meaning'),Q(1,'Trademark combines…','trade and mark','track and pad','town and people','The compound names a mark used in commerce.','word-formation')]);
P('trader','Trader is formed from trade plus the agent suffix -er; it names a person or company buying and selling goods, or a person dealing in financial products.',[C('trader.s1','商品交易','The trader specializes in second-hand machinery and ships it to farms.','这位商人专营二手机械，并把机器运往农场。','grain/oil trader; independent trader','名词，指买卖商品、尤指大量商品的人或公司。','the person buys and sells machinery.','商品交易'),C('trader.s2','金融交易','The bank hired twenty new traders to manage shares and currency deals.','银行新雇了二十名交易员，负责股票和货币交易。','stock/currency trader; financial trader','名词，指买卖股票、货币或其他金融产品的人。','the employees deal in financial assets.','金融交易')],M('The trader specialized in machinery but never bought or sold any goods.','The trader bought and sold second-hand machinery for farms.','trader指从事买卖的人，完全不进行交易与此不符。','meaning'),[Q(1,'A machinery trader…','buys and sells machinery','designs every farm field','writes a political tract','Sense 1 concerns goods.','meaning'),Q(2,'A currency trader deals in…','financial products and exchange','farm ploughs only','theatre tickets for children','Sense 2 is the financial use.','context'),Q(1,'Which phrase is natural?','a trader in machinery','a machinery traderly in','trader to machinery of','A trader in something buys and sells it.','grammar'),Q(1,'The suffix -er in trader marks…','a person or company that trades','a place where a play is shown','a condition of being hot','It forms an agent noun from trade.','word-formation')]);
P('tradesperson','Tradesperson combines trade with person; it is a gender-neutral word for someone who practises a skilled craft or occupation.',C('tradesperson.s1','职业','We hired a licensed tradesperson to fit the new boiler safely.','我们请了一位持证技工安全安装新锅炉。','licensed/skilled tradesperson; hire a tradesperson','名词，指通过学习掌握实用技能并从事某种手艺职业的人。','the worker has practical installation skills.','职业'),M('We hired a tradesperson to fit the boiler, although the worker had no practical skill or trade training.','We hired a trained tradesperson to fit the boiler safely.','tradesperson指从事技能职业的人，缺乏相关技能不符合所指角色。','meaning'),[Q(1,'A tradesperson is…','someone working in a skilled practical occupation','a person who only visits a town','a legal testament','That is the source definition.','meaning'),Q(1,'Why hire the tradesperson?','To fit the new boiler safely','To perform in a tournament','To map a townscape','The context gives the practical task.','context'),Q(1,'Which phrase is natural?','a licensed tradesperson','a tradespersonly licensed','a licensed trade of person','Licensed modifies the person’s professional status.','grammar'),Q(1,'Tradesperson combines…','trade and person','tour and tourism','terror and -ism','The compound provides a gender-neutral occupational noun.','word-formation')]);
P('trading','Trading is formed from trade plus -ing; it names buying and selling goods, services, or currency and the business activity of taking part in exchanges.',[C('trading.s1','贸易','Trading with neighbouring countries expanded after the border reopened.','边境重新开放后，与邻国的贸易扩大了。','international trading; trading in goods','名词，指商品、服务或货币的买卖活动。','the countries exchange goods through commerce.','贸易'),C('trading.s2','交易活动','The new rules limit trading in shares during the final minutes of the market day.','新规限制交易日最后几分钟的股票交易。','share/currency trading; trading activity','名词，指作为商业行为参与买卖或金融交易。','the rule regulates participation in market deals.','交易活动')],M('Trading expanded after the border reopened, but no goods, services, or currency were bought or sold.','Trading expanded after the border reopened as businesses exchanged goods and services.','trading指实际的买卖交换；完全没有交易就不能说活动扩大。','meaning'),[Q(1,'Trading with neighbouring countries is…','commercial exchange across borders','a group’s naming ritual','a storm over farmland','Sense 1 is cross-border commerce.','meaning'),Q(2,'Trading in shares refers to…','buying and selling stock','printing a textbook','moving toward a station','Sense 2 is market activity.','context'),Q(1,'Which phrase is natural?','trading in shares','trading sharesly in','shares to trading of','In introduces the market item being traded.','grammar'),Q(1,'Trading is formed by adding -ing to…','trade','town','toxic','The ending creates a noun for the activity.','word-formation')]);
P('tradition','Tradition comes from Latin traditio, “handing over,” from tradere, “deliver”; it is a custom passed down over time or the accumulated beliefs and practices of a group.',[C('tradition.s1','习俗','It is a family tradition to cook dumplings together on the first day of the new year.','新年第一天一起包饺子是他们家的传统。','family/local tradition; follow a tradition','名词，指长期存在并代代相传的习俗或信念。','the custom is repeated over generations.','习俗'),C('tradition.s2','传统体系','The school is proud of its tradition of public service and careful research.','这所学校以公共服务和严谨研究的传统为荣。','a tradition of learning; cultural tradition','名词，指一个群体长期传承的一整套信念和做法。','the school maintains established values and practices.','传统体系')],M('The family tradition was passed down, although no family member ever repeated or taught it to anyone.','The family tradition was passed down as relatives cooked together each new year.','传统需要在群体中延续和传承，原句否认任何传递或实践。','meaning'),[Q(1,'A family tradition is…','a custom passed down over time','a one-time accidental event','a place where plays are shown','Sense 1 is a repeated inherited custom.','meaning'),Q(2,'A school’s tradition of research is…','an established set of values and practices','one student’s private hobby only','a single day on a calendar','Sense 2 is the wider group practice.','context'),Q(1,'Which phrase is natural?','follow a tradition','tradition followly','follow to a tradition','Follow takes the custom as its object.','grammar'),Q(1,'Latin tradere, behind tradition, meant…','to deliver or hand over','to turn a wheel','to terrify','The origin reflects customs being handed down.','word-formation')]);
P('traditional','Traditional is formed from tradition plus -al; it describes long-established customs, folklore passed among ordinary people, or accepted forms in a field.',[C('traditional.s1','习俗','They serve traditional food at the inn, using recipes passed down through the family.','旅店供应传统菜肴，菜谱由家族代代相传。','traditional food/custom; traditional method','形容词，指遵循长期确立的习俗、方法或信念的。','the recipes are inherited and long established.','习俗'),C('traditional.s2','民间传统','The band plays traditional tunes that local musicians learned by ear.','乐队演奏当地音乐家凭耳朵学来的民间传统曲调。','traditional music/folk tale; traditional craft','形容词，指在普通人群中口传或传承下来的故事、歌曲与技艺。','the tunes are passed through community practice.','民间传统'),C('traditional.s3','既定形式','He trained in traditional medicine before studying modern clinical research.','他先学习传统医学，之后才研究现代临床研究。','traditional medicine/art; traditional approach','形容词，指遵循某门宗教、艺术或学科中已被接受的形式。','the practice follows an established system.','既定形式')],M('The inn served traditional food made from a recipe invented moments ago with no link to any established custom.','The inn served traditional food prepared from a recipe passed down through the family.','traditional food遵循长期传承的做法，临时发明且无传承不符合。','meaning'),[Q(1,'Traditional food is…','prepared according to long-established customs','always newly invented for one meal','a kind of political movement','Sense 1 is the customary use.','meaning'),Q(2,'Traditional tunes learned by ear are…','songs passed along in a community','recordings made only by machines','a court statement','Sense 2 concerns folk transmission.','context'),Q(3,'Traditional medicine is…','a practice following accepted forms in a medical tradition','a new method with no history','a tool for measuring force','Sense 3 is a field-specific established practice.','meaning'),Q(1,'The suffix -al in traditional forms…','an adjective meaning related to tradition','a noun for a person','a verb for buying and selling','Traditional means connected with tradition.','word-formation')]);
P('traditionalist','Traditionalist is formed from traditional plus -ist; it names a person who values older customs and tends to dislike new methods.',C('traditionalist.s1','守旧者','As a traditionalist in the kitchen, he prefers the family recipe to new cooking techniques.','作为厨房里的传统主义者，他更喜欢家传食谱，不太喜欢新烹饪方法。','a political/cultural traditionalist; remain a traditionalist','名词，指偏爱旧习俗并反感新方法的人。','he consistently chooses the established recipe.','守旧者'),M('As a traditionalist, she eagerly discarded every old custom and welcomed any new method.','As a traditionalist, she kept familiar customs and resisted unfamiliar methods.','traditionalist指偏爱传统并倾向拒绝新方法，与主动抛弃旧习相反。','meaning'),[Q(1,'A traditionalist tends to…','prefer established customs and methods','reject every old custom','sell goods in a market','That is the source sense.','meaning'),Q(1,'Why does he prefer the family recipe?','He values the established cooking tradition','He is a tourist in town','He wants to apply a tourniquet','The example links his choice with traditionalism.','context'),Q(1,'Which phrase is natural?','a traditionalist in the kitchen','a traditionalist kitchenly in','traditionalist of kitchen to','In identifies the field or setting.','grammar'),Q(1,'The suffix -ist often names…','a person associated with a belief or practice','a location for an event','a past-tense verb','Traditionalist names a person with a traditional preference.','word-formation')]);
P('traditionally','Traditionally is formed from traditional plus -ly; it means in a way that follows long-established custom or as has usually been the case.',C('traditionally.s1','按传统','Traditionally, the festival begins at dusk after families finish their evening meal.','按照传统，节日会在各家吃完晚饭后的黄昏时开始。','traditionally served/held; traditionally, ...','副词，指依照长期习俗，或按照通常发生的情况。','the timing follows an established custom.','按传统'),M('Traditionally, the festival always began at noon, but the sentence says it begins at dusk.','Traditionally, the festival begins at dusk after the evening meal.','traditionally表示按既有惯例，此处习惯时间是黄昏而非正午。','meaning'),[Q(1,'Traditionally, the festival begins at dusk means…','that is the customary time','that is a one-time change with no custom','the festival ends before it starts','The adverb indicates an established pattern.','meaning'),Q(1,'What happens before the festival begins?','Families finish their evening meal','They travel to Toronto','They apply a topcoat','The context gives the sequence.','context'),Q(1,'Which placement is natural?','Traditionally, the festival begins at dusk.','The festival traditionallyly begins at duskly.','Tradition the festival begins at dusk.','Traditionally can introduce a sentence as an adverb.','grammar'),Q(1,'Traditionally is formed from…','traditional plus -ly','trade plus -er','traduce plus -ing','The suffix forms an adverb from the adjective.','word-formation')]);
P('traduce','Traduce comes from Latin traducere, “lead across or expose to shame,” from trans- and ducere, “lead”; today it means speak maliciously and falsely to damage someone’s reputation.',C('traduce.s1','诽谤','The article traduced the scientist with false claims that damaged her reputation.','那篇文章用虚假说法诽谤了这位科学家，损害了她的声誉。','traduce someone’s reputation; maliciously traduce','动词，指恶意散布关于某人的虚假言论以损害其名誉。','the claims are both malicious and false.','诽谤'),M('The article traduced the scientist by publishing accurate praise that improved her reputation.','The article traduced the scientist by publishing malicious falsehoods about her.','traduce表示以恶意虚假言论损害名誉，不是准确赞扬。','meaning'),[Q(1,'To traduce a scientist is to…','maliciously and falsely damage her reputation','praise her with a factual review','invite her to a town tour','That is the verb’s meaning.','meaning'),Q(1,'What did the article publish?','False claims','A verified award citation','A topographical map','The context says the claims were false.','context'),Q(1,'Which phrase is natural?','traduce someone’s reputation','traduce a reputation for praise','reputation traduce ofly','A person’s reputation is the object being damaged.','grammar'),Q(1,'Latin traducere meant…','to lead across or expose to shame','to pull a plough','to dry a surface','The modern reputation sense developed from the Latin idea of bringing into disgrace.','word-formation')]);
P('traffic','Traffic came through French/Italian forms related to trading, though the deeper origin is uncertain; it means road vehicles, movement of goods or messages, illegal trade, or to deal in illegal goods.',[C('traffic.s1','道路车辆','Traffic was heavy this morning, so the bus arrived fifteen minutes late.','今天早上道路交通拥堵，所以公交车晚到了十五分钟。','heavy/light traffic; traffic jam','名词，指道路上行驶的车辆及其流动情况。','many vehicles slow the bus.','道路车辆'),C('traffic.s2','流动','Website traffic doubled after the museum launched its online exhibit.','博物馆推出线上展览后，网站访问量翻了一倍。','air/website/data traffic; traffic between places','名词，指船只、飞机、货物或信息的往来流动。','more users visit the website.','流动'),C('traffic.s3','非法买卖','The court convicted the gang of traffic in stolen art.','法院判定该团伙参与倒卖赃物艺术品。','drug/arms/human traffic; traffic in stolen goods','名词，指非法购买和销售某物。','the group trades stolen property illegally.','非法买卖'),C('traffic.s4','非法交易','The gang trafficked in weapons across the border for several years.','该团伙多年来在边境两侧非法贩运武器。','traffic in drugs/weapons; traffick goods','动词，指非法买卖或贩运某种物品。','weapons are transported and sold illegally.','非法交易')],M('Traffic was heavy, so the roads were completely empty and the bus arrived early.','Traffic was heavy, so many vehicles slowed the bus and delayed its arrival.','heavy traffic表示车辆多、通行慢，与道路空旷相反。','meaning'),[Q(1,'Heavy traffic on the road means…','many vehicles are moving along it','many books are being edited','the town has no streets','Sense 1 is road movement.','meaning'),Q(2,'Website traffic doubled means…','twice as many visits reached the site','the website was pulled behind a truck','road cars doubled in the city','Sense 2 is movement of visitors or data.','context'),Q(3,'Traffic in stolen art is…','illegal buying and selling','legal museum attendance','a sport tournament','Sense 3 is the noun for illegal trade.','meaning'),Q(4,'The gang trafficked in weapons means it…','illegally bought, sold, or moved weapons','tracked weather satellites','painted a tower','Sense 4 is the verb.','context')]);
P('tragedy','Tragedy came through French and Latin from Greek tragodia, often interpreted as “goat song,” though the explanation is debated; it means a very sad event or a serious play with a sorrowful ending.',[C('tragedy.s1','悲剧事件','The crash was a tragedy that took several lives and devastated the community.','这场事故是一场悲剧，夺走数条生命并摧毁了社区。','a terrible tragedy; a family/national tragedy','名词，指造成死亡、痛苦或巨大损失的悲惨事件。','the crash causes lasting grief and harm.','悲剧事件'),C('tragedy.s2','悲剧作品','The students studied a Greek tragedy in which the hero’s choices led to a sorrowful ending.','学生们学习了一部希腊悲剧，其中主人公的选择导致悲伤结局。','Greek/Shakespearean tragedy; tragic play','名词，指结局悲惨严肃的戏剧或故事。','the play ends in loss rather than comedy.','悲剧作品')],M('The crash was a tragedy, but it caused no harm, loss, sorrow, or suffering to anyone.','The crash was a tragedy because it caused death and lasting grief.','tragedy指造成严重悲伤或损失的事件，毫无伤害与之相反。','meaning'),[Q(1,'A crash described as a tragedy is…','a very sad event involving suffering or loss','a harmless comedy','a short technical pamphlet','Sense 1 is the event meaning.','meaning'),Q(2,'A Greek tragedy is…','a serious play with a sorrowful ending','a lively comedy with no conflict','a sports tournament','Sense 2 is the dramatic genre.','context'),Q(1,'Which phrase is natural?','a national tragedy','a tragedyful national','national of a tragedyly','National modifies the event.','grammar'),Q(1,'Greek tragodia is often glossed as…','“goat song,” though the history is debated','“top coat,” with certainty','“town people”','The conventional etymology is commonly offered but not certain.','word-formation')]);
})(typeof window!=='undefined'?window:globalThis);
